PROGRAM BeltSpeed

VAR_INPUT
    TurnUp : BOOL; (* Knob up: one press adds 512 counts *)
    TurnDown : BOOL; (* Knob down: one press takes away 512 counts *)
END_VAR

VAR
    Ups : DINT := 0; (* Counts added by the knob so far *)
    Downs : DINT := 0; (* Counts taken away by the knob so far *)
    Knob : DINT := 0; (* Stand-in for the sensor before the limit *)
    Raw : DINT := 0; (* The analog input in counts, 0..4095 *)
    Scaled : DINT := 0; (* Raw times 1500: 6 142 500 at full scale, far above what an INT holds *)
    Speed : DINT := 0; (* Belt speed in millimetres per second, 0..1500 *)
    _rung1_result : BOOL;
    _edge_r1_r1_0 : R_TRIG;
    _rung2_result : BOOL;
    _edge_r2_r2_0 : R_TRIG;
    _rung3_result : BOOL;
    _rung4_result : BOOL;
    _rung5_result : BOOL;
    _rung6_result : BOOL;
    _rung7_result : BOOL;
END_VAR

VAR_OUTPUT
    Moving : BOOL; (* Lamp: 750 mm/s or more *)
    Overspeed : BOOL; (* Lamp: more than 1200 mm/s *)
END_VAR

(* LD Execution - Auto-generated *)

(* Rung 1: One press of TurnUp is one pulse that adds 512 counts. *)
_edge_r1_r1_0(CLK := TurnUp);
_rung1_result := _edge_r1_r1_0.Q;
IF _rung1_result THEN Ups := Ups + 512; END_IF;

(* Rung 2: One press of TurnDown takes 512 counts away. *)
_edge_r2_r2_0(CLK := TurnDown);
_rung2_result := _edge_r2_r2_0.Q;
IF _rung2_result THEN Downs := Downs + 512; END_IF;

(* Rung 3: The knob position is what went up minus what went down. *)
_rung3_result := TRUE;
IF _rung3_result THEN Knob := Ups - Downs; END_IF;

(* Rung 4: LIMIT keeps the counts inside the range of a 12-bit input. *)
_rung4_result := TRUE;
IF _rung4_result THEN Raw := LIMIT(0, Knob, 4095); END_IF;

(* Rung 5: Counts to millimetres per second: multiply by the span of the speed, then divide by the span of the counts. *)
_rung5_result := TRUE;
IF _rung5_result THEN Scaled := Raw * 1500; END_IF;
IF _rung5_result THEN Speed := Scaled / 4095; END_IF;

(* Rung 6: Moving from 750 mm/s. *)
_rung6_result := Speed >= 750;
Moving := _rung6_result;

(* Rung 7: Overspeed lamp above 1200 mm/s. *)
_rung7_result := Speed > 1200;
Overspeed := _rung7_result;

END_PROGRAM

