PROGRAM CaseAverage

VAR_INPUT
    AddLight : BOOL; (* A light bottle (280 g) enters the case *)
    AddHeavy : BOOL; (* A heavy bottle (360 g) enters the case *)
END_VAR

VAR
    Lights : DINT := 0; (* Light bottles in the case *)
    Heavies : DINT := 0; (* Heavy bottles in the case *)
    LightGrams : DINT := 0; (* Weight of the light bottles in grams *)
    HeavyGrams : DINT := 0; (* Weight of the heavy bottles in grams *)
    Weight : DINT := 0; (* Total weight of the case in grams *)
    Bottles : DINT := 0; (* Bottles in the case *)
    Average : DINT := 0; (* Average weight of a bottle in grams *)
    _rung1_result : BOOL;
    _edge_r1_r1_0 : R_TRIG;
    _rung2_result : BOOL;
    _edge_r2_r2_0 : R_TRIG;
    _rung3_result : BOOL;
    _rung4_result : BOOL;
    _rung5_result : BOOL;
    _rung6_result : BOOL;
    _rung7_result : BOOL;
END_VAR

VAR_OUTPUT
    Heavy : BOOL; (* Lamp: the average is above 300 g *)
    Empty : BOOL; (* Lamp: no bottle in the case *)
END_VAR

(* LD Execution - Auto-generated *)

(* Rung 1: A light bottle: count one more. *)
_edge_r1_r1_0(CLK := AddLight);
_rung1_result := _edge_r1_r1_0.Q;
IF _rung1_result THEN Lights := Lights + 1; END_IF;

(* Rung 2: A heavy bottle: count one more. *)
_edge_r2_r2_0(CLK := AddHeavy);
_rung2_result := _edge_r2_r2_0.Q;
IF _rung2_result THEN Heavies := Heavies + 1; END_IF;

(* Rung 3: Three boxes in series, with no contact: each runs on every scan, from left to right. *)
_rung3_result := TRUE;
IF _rung3_result THEN LightGrams := Lights * 280; END_IF;
IF _rung3_result THEN HeavyGrams := Heavies * 360; END_IF;
IF _rung3_result THEN Weight := LightGrams + HeavyGrams; END_IF;

(* Rung 4: The number of bottles in the case. *)
_rung4_result := TRUE;
IF _rung4_result THEN Bottles := Lights + Heavies; END_IF;

(* Rung 5: The guard: NE conducts only when Bottles is not zero, so the DIV never receives a zero divisor. *)
_rung5_result := Bottles <> 0;
IF _rung5_result THEN Average := Weight / Bottles; END_IF;

(* Rung 6: Heavy while the average is above 300 g. *)
_rung6_result := Average > 300;
Heavy := _rung6_result;

(* Rung 7: Empty while there is no bottle. *)
_rung7_result := Bottles = 0;
Empty := _rung7_result;

END_PROGRAM

PROGRAM TankAlarm

VAR_INPUT
    Fill : BOOL; (* Inlet valve pushbutton: one press adds 25 liters *)
    Drain : BOOL; (* Outlet valve pushbutton: one press takes 25 liters *)
END_VAR

VAR
    Filled : DINT := 0; (* Liters that have come in so far *)
    Drained : DINT := 0; (* Liters that have gone out so far *)
    Level : DINT := 0; (* Liters in the tank: Filled minus Drained *)
    _rung1_result : BOOL;
    _edge_r1_r1_0 : R_TRIG;
    _rung2_result : BOOL;
    _edge_r2_r2_0 : R_TRIG;
    _rung3_result : BOOL;
    _rung4_result : BOOL;
END_VAR

VAR_OUTPUT
    HighAlarm : BOOL; (* Lamp: more than 100 liters *)
END_VAR

(* LD Execution - Auto-generated *)

(* Rung 1: One press of Fill is one pulse: the box adds 25 liters once and keeps the result. *)
_edge_r1_r1_0(CLK := Fill);
_rung1_result := _edge_r1_r1_0.Q;
IF _rung1_result THEN Filled := Filled + 25; END_IF;

(* Rung 2: One press of Drain adds 25 liters to the total that went out. *)
_edge_r2_r2_0(CLK := Drain);
_rung2_result := _edge_r2_r2_0.Q;
IF _rung2_result THEN Drained := Drained + 25; END_IF;

(* Rung 3: Level is what came in minus what went out. The box has no contact, so it runs on every scan. *)
_rung3_result := TRUE;
IF _rung3_result THEN Level := Filled - Drained; END_IF;

(* Rung 4: A comparison is a condition in series: the lamp is on while Level is above 100. *)
_rung4_result := Level > 100;
HighAlarm := _rung4_result;

END_PROGRAM

