PROGRAM CarWash

VAR
    Go : BOOL; (* Start button *)
    StepSoap : BOOL := FALSE; (* Soap step *)
    StepRinse : BOOL := FALSE; (* Rinse step *)
    SoapTimer : TON; (* Soap time *)
    RinseTimer : TON; (* Rinse time *)
    _rung1_result : BOOL;
    _rung2_result : BOOL;
    _rung3_result : BOOL;
    _rung4_result : BOOL;
    _rung5_result : BOOL;
    _rung6_result : BOOL;
    _rung7_result : BOOL;
    _rung8_result : BOOL;
END_VAR

VAR_OUTPUT
    Soap : BOOL; (* Soap sprayer *)
    Rinse : BOOL; (* Rinse sprayer *)
END_VAR

(* LD Execution - Auto-generated *)

(* Rung 1: Go starts the wash, but only when no step is active. *)
_rung1_result := Go AND NOT StepSoap AND NOT StepRinse;
IF _rung1_result THEN StepSoap := TRUE; END_IF;

(* Rung 2: Soap to rinse, part 1: when the soap time is over, the rinse step becomes active. *)
_rung2_result := StepSoap AND SoapTimer.Q;
IF _rung2_result THEN StepRinse := TRUE; END_IF;

(* Rung 3: Soap to rinse, part 2: the same condition ends the soap step. *)
_rung3_result := StepSoap AND SoapTimer.Q;
IF _rung3_result THEN StepSoap := FALSE; END_IF;

(* Rung 4: The rinse step ends when its time is over. *)
_rung4_result := StepRinse AND RinseTimer.Q;
IF _rung4_result THEN StepRinse := FALSE; END_IF;

(* Rung 5: Soap time. *)
_rung5_result := StepSoap;
SoapTimer(IN := _rung5_result, PT := T#2s);

(* Rung 6: Rinse time. *)
_rung6_result := StepRinse;
RinseTimer(IN := _rung6_result, PT := T#2s);

(* Rung 7: Soap sprayer follows its step. *)
_rung7_result := StepSoap;
Soap := _rung7_result;

(* Rung 8: Rinse sprayer follows its step. *)
_rung8_result := StepRinse;
Rinse := _rung8_result;

END_PROGRAM

