PROGRAM TankMonitor

VAR_INPUT
    Setup AT %IX0.0 : BOOL; (* Setup pushbutton: TRUE while pressed *)
    Fill AT %IX0.1 : BOOL; (* Inlet valve open: TRUE adds 25 liters per scan *)
    Drain AT %IX0.2 : BOOL; (* Outlet valve open: TRUE removes 25 liters per scan *)
END_VAR

VAR
    Filled : DINT := 0; (* Liters that have come in so far *)
    Drained : DINT := 0; (* Liters that have gone out so far *)
    Level : DINT := 0; (* Liters in the tank: Filled minus Drained *)
    Capacity : DINT := 0; (* Capacity of the tank in liters: 0 until Setup copies it *)
    Scaled : DINT := 0; (* Level times 100, the intermediate product *)
    Percent : DINT := 0; (* Level as a percentage of Capacity *)
    _rung1_result : BOOL;
    _rung2_result : BOOL;
    _rung3_result : BOOL;
    _rung4_result : BOOL;
    _rung5_result : BOOL;
    _rung6_result : BOOL;
    _rung7_result : BOOL;
END_VAR

VAR_OUTPUT
    Configured AT %QX0.0 : BOOL; (* Lamp: the capacity is known *)
    HighAlarm AT %QX0.1 : BOOL; (* Lamp: the tank is at least 75 percent full *)
END_VAR

(* LD Execution - Auto-generated *)

(* Rung 1: Setup copies the capacity once. Capacity keeps 200 after Setup is released. *)
_rung1_result := Setup;
IF _rung1_result THEN Capacity := 200; END_IF;

(* Rung 2: While Fill has power the box adds 25 liters each scan; without power Filled keeps its value. *)
_rung2_result := Fill;
IF _rung2_result THEN Filled := Filled + 25; END_IF;

(* Rung 3: While Drain has power the box adds 25 liters to the total that went out. *)
_rung3_result := Drain;
IF _rung3_result THEN Drained := Drained + 25; END_IF;

(* Rung 4: No contact: the box has power on every scan, so Level always follows the two totals. *)
_rung4_result := TRUE;
IF _rung4_result THEN Level := Filled - Drained; END_IF;

(* Rung 5: The lamp is on while Capacity is not zero. *)
_rung5_result := Capacity <> 0;
Configured := _rung5_result;

(* Rung 6: Percent = Level x 100 / Capacity. NE in series keeps the DIV from ever seeing a zero divisor. *)
_rung6_result := Capacity <> 0;
IF _rung6_result THEN Scaled := Level * 100; END_IF;
IF _rung6_result THEN Percent := Scaled / Capacity; END_IF;

(* Rung 7: The alarm is a comparison in series with the coil. *)
_rung7_result := Percent >= 75;
HighAlarm := _rung7_result;

END_PROGRAM

