PROGRAM PackStation

VAR_INPUT
    Start AT %I0.0 : BOOL; (* Start pushbutton, normally open: TRUE while pressed *)
    StopOK AT %I0.1 : BOOL; (* Stop pushbutton wired normally closed: TRUE at rest, FALSE while pressed *)
    EStopOK AT %I0.2 : BOOL; (* Emergency stop wired normally closed: TRUE at rest, FALSE while pressed *)
    Part AT %I0.3 : BOOL; (* Part sensor: TRUE while a part is in front of it *)
    Reset AT %I0.4 : BOOL; (* Reset pushbutton, normally open: TRUE while pressed *)
END_VAR

VAR
    Count : CTU; (* Part counter: Count.CV is the number of parts so far *)
    Stuck : TON; (* Blocked-sensor timer: times how long Part stays on *)
    _rung1_result : BOOL;
    _rung1_result_2 : BOOL;
    _rung2_result : BOOL;
    _rung2_result_2 : BOOL;
    _rung3_result : BOOL;
    _rung4_result : BOOL;
END_VAR

VAR_OUTPUT
    Belt AT %Q0.0 : BOOL; (* Belt motor command. It is also the memory that keeps the belt running. *)
    BatchFull AT %Q0.1 : BOOL; (* Batch lamp: TRUE once the batch is complete *)
    Fault AT %Q0.2 : BOOL; (* Fault lamp: TRUE while a blocked sensor fault is latched *)
END_VAR

(* LD Execution - Auto-generated *)

(* Rung 1: Each rising edge of Part counts one part; BatchFull follows the counter output once three parts are counted, and Reset clears the count. *)
_rung1_result := Part;
Count(CU := _rung1_result, R := Reset, PV := 3);
_rung1_result_2 := Count.Q;
BatchFull := _rung1_result_2;

(* Rung 2: If Part stays on for the preset, the sensor is blocked: set the latched Fault. *)
_rung2_result := Part;
Stuck(IN := _rung2_result, PT := T#80ms);
_rung2_result_2 := Stuck.Q;
IF _rung2_result_2 THEN Fault := TRUE; END_IF;

(* Rung 3: Reset clears Fault only when the part sensor is clear again. *)
_rung3_result := Reset AND NOT Part;
IF _rung3_result THEN Fault := FALSE; END_IF;

(* Rung 4: Seal-in for the belt. StopOK, EStopOK, Fault and BatchFull are in series after the branch, so any of them drops the belt and only a new Start restarts it. *)
_rung4_result := (Start OR Belt) AND StopOK AND EStopOK AND NOT Fault AND NOT BatchFull;
Belt := _rung4_result;

END_PROGRAM

