PROGRAM TankLevel

VAR_INPUT
    AutoEnable AT %I0.0 : BOOL; (* Automatic mode: TRUE while the pump may run *)
    LevelLow AT %I0.1 : BOOL; (* Low-level sensor of the tank plant: TRUE while the level is low *)
    LevelHigh AT %I0.2 : BOOL; (* High-level sensor of the tank plant: TRUE while the tank is full *)
    PumpFault AT %I0.3 : BOOL; (* Pump fault from the plant: TRUE while the pump reports a fault *)
    EStop AT %I0.4 : BOOL; (* Emergency stop, active-high here: TRUE while pressed *)
    Reset AT %I0.5 : BOOL; (* Reset pushbutton, normally open: TRUE while pressed *)
END_VAR

VAR
    FaultLatched : BOOL := FALSE; (* A fault happened and has not been reset *)
    ResetArmed : BOOL := FALSE; (* Reset has been seen released while the fault was latched *)
    _rung1_result : BOOL;
    _rung2_result : BOOL;
    _rung3_result : BOOL;
    _rung4_result : BOOL;
    _rung5_result : BOOL;
    _rung6_result : BOOL;
END_VAR

VAR_OUTPUT
    Pump AT %Q0.0 : BOOL; (* Pump command. It is also the memory that keeps the fill going until LevelHigh. *)
    Alarm AT %Q0.1 : BOOL; (* Alarm: a fault is present or latched *)
END_VAR

(* LD Execution - Auto-generated *)

(* Rung 1: A fault (EStop or PumpFault) sets FaultLatched; the latch keeps the fault after the input has gone away. *)
_rung1_result := EStop OR PumpFault;
IF _rung1_result THEN FaultLatched := TRUE; END_IF;

(* Rung 2: Reset is disarmed while a fault input is present, and once the latch is cleared: it must be released and pressed again after each fault. *)
_rung2_result := EStop OR PumpFault OR NOT FaultLatched;
IF _rung2_result THEN ResetArmed := FALSE; END_IF;

(* Rung 3: Reset seen released while the fault is latched and no fault input is present: arm it. *)
_rung3_result := FaultLatched AND NOT Reset AND NOT EStop AND NOT PumpFault;
IF _rung3_result THEN ResetArmed := TRUE; END_IF;

(* Rung 4: A fresh Reset press while armed and with no fault input present clears the latch. *)
_rung4_result := FaultLatched AND ResetArmed AND Reset AND NOT EStop AND NOT PumpFault;
IF _rung4_result THEN FaultLatched := FALSE; END_IF;

(* Rung 5: Pump with seal-in: LevelLow starts the fill and the pump holds itself on until LevelHigh; every stop condition is in series, so none can be bypassed. *)
_rung5_result := AutoEnable AND NOT LevelHigh AND NOT FaultLatched AND NOT EStop AND NOT PumpFault AND (LevelLow OR Pump);
Pump := _rung5_result;

(* Rung 6: Alarm: a fault is present now, or it is latched. *)
_rung6_result := FaultLatched OR EStop OR PumpFault;
Alarm := _rung6_result;

END_PROGRAM

