PROGRAM Opta_LED_Chaser

VAR
    Tick : BOOL := FALSE; (* TRUE for one scan every 150 ms + 2 scans *)
    TimerInst : TON;
    Carry : BOOL := FALSE;
    P0 : BOOL := TRUE; (* Position 0 of the 6-step bounce (D0 D1 D2 D3 D2 D1) *)
    P1 : BOOL := FALSE;
    P2 : BOOL := FALSE;
    P3 : BOOL := FALSE;
    P4 : BOOL := FALSE;
    P5 : BOOL := FALSE;
    _rung1_result : BOOL;
    _rung2_result : BOOL;
    _rung3_result : BOOL;
    _rung4_result : BOOL;
    _rung5_result : BOOL;
    _rung6_result : BOOL;
    _rung7_result : BOOL;
    _rung8_result : BOOL;
    _rung9_result : BOOL;
    _rung10_result : BOOL;
    _rung11_result : BOOL;
    _rung12_result : BOOL;
END_VAR

VAR_OUTPUT
    LED_D0 AT %Q0.0 : BOOL;
    LED_D1 AT %Q0.1 : BOOL;
    LED_D2 AT %Q0.2 : BOOL;
    LED_D3 AT %Q0.3 : BOOL;
END_VAR

(* LD Execution - Auto-generated *)

(* Rung 1: 150 ms tick: TimerInst runs while Tick is FALSE; its Q is Tick, TRUE for one scan, which resets it *)
_rung1_result := NOT Tick;
TimerInst(IN := _rung1_result, PT := T#150ms);
Tick := TimerInst.Q;

(* Rung 2: Carry = P5 before the shift (P0 takes it back at the end) *)
_rung2_result := P5;
Carry := _rung2_result;

(* Rung 3: P5 takes P4 on a tick, holds otherwise *)
_rung3_result := (Tick AND P4) OR (NOT Tick AND P5);
P5 := _rung3_result;

(* Rung 4: P4 takes P3 on a tick, holds otherwise *)
_rung4_result := (Tick AND P3) OR (NOT Tick AND P4);
P4 := _rung4_result;

(* Rung 5: P3 takes P2 on a tick, holds otherwise *)
_rung5_result := (Tick AND P2) OR (NOT Tick AND P3);
P3 := _rung5_result;

(* Rung 6: P2 takes P1 on a tick, holds otherwise *)
_rung6_result := (Tick AND P1) OR (NOT Tick AND P2);
P2 := _rung6_result;

(* Rung 7: P1 takes P0 on a tick, holds otherwise *)
_rung7_result := (Tick AND P0) OR (NOT Tick AND P1);
P1 := _rung7_result;

(* Rung 8: P0 takes the carried P5 on a tick, holds otherwise *)
_rung8_result := (Tick AND Carry) OR (NOT Tick AND P0);
P0 := _rung8_result;

(* Rung 9: D0 lit at position 0 *)
_rung9_result := P0;
LED_D0 := _rung9_result;

(* Rung 10: D1 lit at positions 1 and 5 (going out and coming back) *)
_rung10_result := P1 OR P5;
LED_D1 := _rung10_result;

(* Rung 11: D2 lit at positions 2 and 4 (going out and coming back) *)
_rung11_result := P2 OR P4;
LED_D2 := _rung11_result;

(* Rung 12: D3 lit at position 3 (the turning point) *)
_rung12_result := P3;
LED_D3 := _rung12_result;

END_PROGRAM

