PROGRAM BeltTransfer

VAR_INPUT
    Start AT %I0.0 : BOOL; (* StartButton.pressed: start the transfer *)
    Waiting AT %I0.1 : BOOL; (* EyePick.detect: a box waits at the stop blade of the infeed *)
    OutEye AT %I0.2 : BOOL; (* EyeOut.detect: a box passes on the outfeed belt *)
    XMin AT %I0.3 : BOOL; (* Pick1.xAtMin: the carriage is over the infeed *)
    XMax AT %I0.4 : BOOL; (* Pick1.xAtMax: the carriage is over the outfeed *)
    YMin AT %I0.5 : BOOL; (* Pick1.yAtMin: the clamp is down *)
    YMax AT %I0.6 : BOOL; (* Pick1.yAtMax: the clamp is up *)
    Gripped AT %I0.7 : BOOL; (* Pick1.gripped: the clamp holds a box *)
END_VAR

VAR
    Active : BOOL := FALSE; (* The transfer was started *)
    State : INT := 0; (* One state per move: 0 idle, 2 wait for a box, 3 lower, 4 close, 5 lift, 6 carry, 7 lower, 8 open and settle, 9 lift, 10 return, 11 finished *)
    Settle : TON; (* A box must stand still at the blade before the clamp comes down *)
    Rest : TON; (* A put-down box must lie still before the outfeed runs again *)
    Lifts : CTU; (* Counts the lifts at the blade: the first three bring the next box *)
    Placed : CTU; (* Counts the boxes put down *)
    Delivered : CTU; (* Counts the boxes that passed EyeOut *)
    _rung1_result : BOOL;
    _rung2_result : BOOL;
    _rung2_result_2 : BOOL;
    _rung2_result_3 : BOOL;
    _rung3_result : BOOL;
    _rung3_result_2 : BOOL;
    _rung4_result : BOOL;
    _rung5_result : BOOL;
    _rung5_result_2 : BOOL;
    _rung6_result : BOOL;
    _rung6_result_2 : BOOL;
    _rung7_result : BOOL;
    _rung8_result : BOOL;
    _rung8_result_2 : BOOL;
    _rung9_result : BOOL;
    _rung9_result_2 : BOOL;
    _rung10_result : BOOL;
    _rung10_result_2 : BOOL;
    _rung11_result : BOOL;
    _rung11_result_2 : BOOL;
    _rung12_result : BOOL;
    _rung12_result_2 : BOOL;
    _rung13_result : BOOL;
    _rung13_result_2 : BOOL;
    _rung14_result : BOOL;
    _rung14_result_2 : BOOL;
    _rung15_result : BOOL;
    _rung15_result_2 : BOOL;
    _rung16_result : BOOL;
    _rung16_result_2 : BOOL;
    _rung17_result : BOOL;
    _rung17_result_2 : BOOL;
    _rung18_result : BOOL;
    _rung18_result_2 : BOOL;
    _rung19_result : BOOL;
    _rung20_result : BOOL;
    _rung21_result : BOOL;
    _rung21_result_2 : BOOL;
    _rung21_result_3 : BOOL;
    _rung21_result_4 : BOOL;
    _rung22_result : BOOL;
    _rung22_result_2 : BOOL;
    _rung22_result_3 : BOOL;
    _rung23_result : BOOL;
    _rung23_result_2 : BOOL;
    _rung23_result_3 : BOOL;
    _rung23_result_4 : BOOL;
    _rung24_result : BOOL;
    _rung24_result_2 : BOOL;
    _rung24_result_3 : BOOL;
    _rung25_result : BOOL;
    _rung25_result_2 : BOOL;
    _rung26_result : BOOL;
    _rung26_result_2 : BOOL;
    _rung26_result_3 : BOOL;
    _rung27_result : BOOL;
    _rung28_result : BOOL;
END_VAR

VAR_OUTPUT
    RunIn AT %Q0.0 : BOOL; (* Infeed.run: run the infeed belt *)
    RunOut AT %Q0.1 : BOOL; (* Outfeed.run: run the outfeed belt *)
    Emit AT %Q0.2 : BOOL; (* Source1.emit: put one box on the infeed belt *)
    Hold AT %Q0.3 : BOOL; (* Stop1.extend: the blade holds the box while true *)
    XPlus AT %Q0.4 : BOOL; (* Pick1.xPlus: move toward the outfeed while true *)
    XMinus AT %Q0.5 : BOOL; (* Pick1.xMinus: move toward the infeed while true *)
    YPlus AT %Q0.6 : BOOL; (* Pick1.yPlus: lift the clamp while true *)
    YMinus AT %Q0.7 : BOOL; (* Pick1.yMinus: lower the clamp while true *)
    Grip AT %Q1.0 : BOOL; (* Pick1.grip: close the clamp while true *)
    Busy AT %Q1.1 : BOOL; (* Beacon.amber: the transfer is running *)
    Done AT %Q1.2 : BOOL; (* Beacon.green: lit when four boxes have crossed the outfeed *)
END_VAR

(* LD Execution - Auto-generated *)

(* Rung 1: Start: a press latches the transfer on. *)
_rung1_result := Start;
IF _rung1_result THEN Active := TRUE; END_IF;

(* Rung 2: Emit: one box on the infeed at the start, and the next one each time a box leaves the blade (the first three lifts). *)
_rung2_result := State = 0;
_rung2_result_2 := State = 5;
_rung2_result_3 := (_rung2_result AND Active) OR (_rung2_result_2 AND YMax AND NOT Lifts.Q);
Emit := _rung2_result_3;

(* Rung 3: Settle time: the box must stand still at the blade for a moment before the clamp comes down. *)
_rung3_result := State = 2;
_rung3_result_2 := _rung3_result AND Waiting;
Settle(IN := _rung3_result_2, PT := T#300ms);

(* Rung 4: Rest time: after the release the box must lie still on the stopped outfeed belt before it runs again. *)
_rung4_result := State = 8;
Rest(IN := _rung4_result, PT := T#600ms);

(* Rung 5: Count the lifts at the blade. *)
_rung5_result := State = 5;
_rung5_result_2 := _rung5_result AND YMax;
Lifts(CU := _rung5_result_2, R := FALSE, PV := 3);

(* Rung 6: Count the boxes put down. *)
_rung6_result := State = 8;
_rung6_result_2 := _rung6_result AND Rest.Q;
Placed(CU := _rung6_result_2, R := FALSE, PV := 4);

(* Rung 7: Count the boxes that pass the end of the outfeed: each rising edge of EyeOut adds one. *)
_rung7_result := OutEye;
Delivered(CU := _rung7_result, R := FALSE, PV := 4);

(* Rung 8: State 10, return: with boxes left, go back to wait for the next one. *)
_rung8_result := State = 10;
_rung8_result_2 := _rung8_result AND XMin AND NOT Placed.Q;
IF _rung8_result_2 THEN State := 2; END_IF;

(* Rung 9: State 10, return: after the fourth box, finish. *)
_rung9_result := State = 10;
_rung9_result_2 := _rung9_result AND XMin AND Placed.Q;
IF _rung9_result_2 THEN State := 11; END_IF;

(* Rung 10: State 9, lift the empty clamp: when it is up, return. *)
_rung10_result := State = 9;
_rung10_result_2 := _rung10_result AND YMax;
IF _rung10_result_2 THEN State := 10; END_IF;

(* Rung 11: State 8, open and settle: when the box lies still, lift. *)
_rung11_result := State = 8;
_rung11_result_2 := _rung11_result AND Rest.Q;
IF _rung11_result_2 THEN State := 9; END_IF;

(* Rung 12: State 7, lower onto the outfeed: when the clamp is down, open it and settle. *)
_rung12_result := State = 7;
_rung12_result_2 := _rung12_result AND YMin;
IF _rung12_result_2 THEN State := 8; END_IF;

(* Rung 13: State 6, carry: when the carriage is over the outfeed, lower. *)
_rung13_result := State = 6;
_rung13_result_2 := _rung13_result AND XMax;
IF _rung13_result_2 THEN State := 7; END_IF;

(* Rung 14: State 5, lift: when the clamp is up, carry. *)
_rung14_result := State = 5;
_rung14_result_2 := _rung14_result AND YMax;
IF _rung14_result_2 THEN State := 6; END_IF;

(* Rung 15: State 4, close: when the clamp holds the box, lift. *)
_rung15_result := State = 4;
_rung15_result_2 := _rung15_result AND Gripped;
IF _rung15_result_2 THEN State := 5; END_IF;

(* Rung 16: State 3, lower: when the clamp is down, close it. *)
_rung16_result := State = 3;
_rung16_result_2 := _rung16_result AND YMin;
IF _rung16_result_2 THEN State := 4; END_IF;

(* Rung 17: State 2, wait for a box: when it is still and the carriage is ready, lower. *)
_rung17_result := State = 2;
_rung17_result_2 := _rung17_result AND Settle.Q AND YMax AND XMin;
IF _rung17_result_2 THEN State := 3; END_IF;

(* Rung 18: State 0, idle: the start moves the first box in. *)
_rung18_result := State = 0;
_rung18_result_2 := _rung18_result AND Active;
IF _rung18_result_2 THEN State := 2; END_IF;

(* Rung 19: The infeed belt runs while the transfer is active. *)
_rung19_result := Active;
RunIn := _rung19_result;

(* Rung 20: The blade holds each box while the transfer is active. *)
_rung20_result := Active;
Hold := _rung20_result;

(* Rung 21: The outfeed belt stands still while a box is carried over it, put down and settling. *)
_rung21_result := State <> 6;
_rung21_result_2 := State <> 7;
_rung21_result_3 := State <> 8;
_rung21_result_4 := Active AND _rung21_result AND _rung21_result_2 AND _rung21_result_3;
RunOut := _rung21_result_4;

(* Rung 22: Grip: the clamp is closed from state 4 to state 7. *)
_rung22_result := State >= 4;
_rung22_result_2 := State <= 7;
_rung22_result_3 := _rung22_result AND _rung22_result_2;
Grip := _rung22_result_3;

(* Rung 23: YPlus: lift in states 2, 5 and 9, until the clamp is up. *)
_rung23_result := State = 2;
_rung23_result_2 := State = 5;
_rung23_result_3 := State = 9;
_rung23_result_4 := (_rung23_result OR _rung23_result_2 OR _rung23_result_3) AND NOT YMax;
YPlus := _rung23_result_4;

(* Rung 24: YMinus: lower in states 3 and 7, until the clamp is down. *)
_rung24_result := State = 3;
_rung24_result_2 := State = 7;
_rung24_result_3 := (_rung24_result OR _rung24_result_2) AND NOT YMin;
YMinus := _rung24_result_3;

(* Rung 25: XPlus: carry toward the outfeed in state 6, until XMax. *)
_rung25_result := State = 6;
_rung25_result_2 := _rung25_result AND NOT XMax;
XPlus := _rung25_result_2;

(* Rung 26: XMinus: return toward the infeed in states 2 and 10, until XMin. *)
_rung26_result := State = 2;
_rung26_result_2 := State = 10;
_rung26_result_3 := (_rung26_result OR _rung26_result_2) AND NOT XMin;
XMinus := _rung26_result_3;

(* Rung 27: Done: lit when four boxes have passed EyeOut. *)
_rung27_result := Delivered.Q;
Done := _rung27_result;

(* Rung 28: Busy: lit while the transfer runs and not yet done. *)
_rung28_result := Active AND NOT Delivered.Q;
Busy := _rung28_result;

END_PROGRAM

