PROGRAM MergeLines

VAR_INPUT
    Start AT %I0.0 : BOOL;
    WaitA AT %I0.1 : BOOL;
    WaitB AT %I0.2 : BOOL;
    Zone AT %I0.3 : BOOL;
END_VAR

VAR
    Active : BOOL;
    GrantA : BOOL;
    GrantB : BOOL;
    Seen : BOOL;
    FullA : BOOL;
    FullB : BOOL;
    LoadedA : CTU;
    LoadedB : CTU;
    Merged : CTU;
    _rung1_result : BOOL;
    _rung2_result : BOOL;
    _edge_r2_contact_n_WaitA_10 : F_TRIG;
    _rung3_result : BOOL;
    _rung3_result_2 : BOOL;
    _edge_r3_contact_n_WaitA_00 : F_TRIG;
    _rung4_result : BOOL;
    _edge_r4_contact_n_WaitB_10 : F_TRIG;
    _rung5_result : BOOL;
    _rung5_result_2 : BOOL;
    _edge_r5_contact_n_WaitB_00 : F_TRIG;
    _rung6_result : BOOL;
    _rung7_result : BOOL;
    _rung8_result : BOOL;
    _rung9_result : BOOL;
    _edge_r9_contact_n_Zone_00 : F_TRIG;
    _rung10_result : BOOL;
    _edge_r10_contact_n_Zone_00 : F_TRIG;
    _rung11_result : BOOL;
    _edge_r11_contact_n_Zone_00 : F_TRIG;
    _rung12_result : BOOL;
    _rung12_result_2 : BOOL;
    _edge_r12_contact_n_Zone_00 : F_TRIG;
    _rung13_result : BOOL;
    _rung14_result : BOOL;
    _rung15_result : BOOL;
    _rung16_result : BOOL;
    _rung17_result : BOOL;
END_VAR

VAR_OUTPUT
    RunA AT %Q0.0 : BOOL;
    RunB AT %Q0.1 : BOOL;
    RunOut AT %Q0.2 : BOOL;
    EmitA AT %Q0.3 : BOOL;
    EmitB AT %Q0.4 : BOOL;
    HoldA AT %Q0.5 : BOOL;
    HoldB AT %Q0.6 : BOOL;
    Done AT %Q0.7 : BOOL;
END_VAR

(* LD Execution - Auto-generated *)

(* Rung 1: Start puts the line to work and Active remembers it. *)
_rung1_result := Start;
IF _rung1_result THEN Active := TRUE; END_IF;

(* Rung 2: Emit A: Start or the box leaving the blade of line A loads the next box, until three have been loaded. *)
_edge_r2_contact_n_WaitA_10(CLK := WaitA);
_rung2_result := (Start OR _edge_r2_contact_n_WaitA_10.Q) AND Active AND NOT FullA;
EmitA := _rung2_result;

(* Rung 3: Count the boxes loaded on line A: three fill the feeder. *)
_edge_r3_contact_n_WaitA_00(CLK := WaitA);
_rung3_result := _edge_r3_contact_n_WaitA_00.Q;
LoadedA(CU := _rung3_result, R := FALSE, PV := 3);
_rung3_result_2 := LoadedA.Q;
FullA := _rung3_result_2;

(* Rung 4: Emit B: Start or the box leaving the blade of line B loads the next box, until three have been loaded. *)
_edge_r4_contact_n_WaitB_10(CLK := WaitB);
_rung4_result := (Start OR _edge_r4_contact_n_WaitB_10.Q) AND Active AND NOT FullB;
EmitB := _rung4_result;

(* Rung 5: Count the boxes loaded on line B: three fill the feeder. *)
_edge_r5_contact_n_WaitB_00(CLK := WaitB);
_rung5_result := _edge_r5_contact_n_WaitB_00.Q;
LoadedB(CU := _rung5_result, R := FALSE, PV := 3);
_rung5_result_2 := LoadedB.Q;
FullB := _rung5_result_2;

(* Rung 6: Grant line A when nothing is granted, the merge zone is free and A waits. *)
_rung6_result := Active AND NOT GrantA AND NOT GrantB AND NOT Zone AND WaitA;
IF _rung6_result THEN GrantA := TRUE; END_IF;

(* Rung 7: Grant line B only when A does not wait. *)
_rung7_result := Active AND NOT GrantA AND NOT GrantB AND NOT Zone AND NOT WaitA AND WaitB;
IF _rung7_result THEN GrantB := TRUE; END_IF;

(* Rung 8: The granted box has reached the merge zone: Seen remembers it. *)
_rung8_result := (GrantA OR GrantB) AND Zone;
IF _rung8_result THEN Seen := TRUE; END_IF;

(* Rung 9: The box has left the merge zone: end the grant (GrantA). *)
_edge_r9_contact_n_Zone_00(CLK := Zone);
_rung9_result := _edge_r9_contact_n_Zone_00.Q AND Seen;
IF _rung9_result THEN GrantA := FALSE; END_IF;

(* Rung 10: The box has left the merge zone: end the grant (GrantB). *)
_edge_r10_contact_n_Zone_00(CLK := Zone);
_rung10_result := _edge_r10_contact_n_Zone_00.Q AND Seen;
IF _rung10_result THEN GrantB := FALSE; END_IF;

(* Rung 11: The box has left the merge zone: end the grant (Seen). *)
_edge_r11_contact_n_Zone_00(CLK := Zone);
_rung11_result := _edge_r11_contact_n_Zone_00.Q AND Seen;
IF _rung11_result THEN Seen := FALSE; END_IF;

(* Rung 12: Count the boxes that left the merge: six light Done. *)
_edge_r12_contact_n_Zone_00(CLK := Zone);
_rung12_result := _edge_r12_contact_n_Zone_00.Q;
Merged(CU := _rung12_result, R := FALSE, PV := 6);
_rung12_result_2 := Merged.Q;
Done := _rung12_result_2;

(* Rung 13: RunA follows Active. *)
_rung13_result := Active;
RunA := _rung13_result;

(* Rung 14: RunB follows Active. *)
_rung14_result := Active;
RunB := _rung14_result;

(* Rung 15: RunOut follows Active. *)
_rung15_result := Active;
RunOut := _rung15_result;

(* Rung 16: Blade A holds line A unless it has the grant. *)
_rung16_result := Active AND NOT GrantA;
HoldA := _rung16_result;

(* Rung 17: Blade B holds line B unless it has the grant. *)
_rung17_result := Active AND NOT GrantB;
HoldB := _rung17_result;

END_PROGRAM

PROGRAM MergeLines

VAR_INPUT
    Start AT %I0.0 : BOOL;
    WaitA AT %I0.1 : BOOL;
    WaitB AT %I0.2 : BOOL;
