PROGRAM ColourSeparation

VAR_INPUT
    Start AT %I0.0 : BOOL; (* StartButton.pressed: start the line *)
    Waiting AT %I0.1 : BOOL; (* EyeBlade.detect: a workpiece waits against the blade *)
    IsRed AT %I0.2 : BOOL; (* ColourSensor.isRed: the workpiece at the blade is red *)
    Extended AT %I0.3 : BOOL; (* Pusher1.extended: the plate is at the end of its stroke *)
    Retracted AT %I0.4 : BOOL; (* Pusher1.retracted: the plate is back at rest *)
END_VAR

VAR
    Active : BOOL := FALSE; (* The line was started *)
    State : INT := 0; (* One state per step: 0 wait for a workpiece, 1 push it out, 2 pull the plate back, 3 let a blue one go by *)
    Settle : TON; (* A workpiece must lie still against the blade before its colour is read *)
    Clear : TON; (* A released workpiece must leave the blade before the blade holds again *)
    Handled : CTU; (* Counts the workpieces dealt with *)
    _rung1_result : BOOL;
    _rung2_result : BOOL;
    _rung2_result_2 : BOOL;
    _rung3_result : BOOL;
    _rung3_result_2 : BOOL;
    _rung4_result : BOOL;
    _rung4_result_2 : BOOL;
    _rung4_result_3 : BOOL;
    _rung5_result : BOOL;
    _rung5_result_2 : BOOL;
    _rung6_result : BOOL;
    _rung6_result_2 : BOOL;
    _rung7_result : BOOL;
    _rung7_result_2 : BOOL;
    _rung8_result : BOOL;
    _rung8_result_2 : BOOL;
    _rung9_result : BOOL;
    _rung9_result_2 : BOOL;
    _rung10_result : BOOL;
    _rung11_result : BOOL;
    _rung12_result : BOOL;
    _rung13_result : BOOL;
    _rung13_result_2 : BOOL;
    _rung14_result : BOOL;
    _rung15_result : BOOL;
    _rung16_result : BOOL;
END_VAR

VAR_OUTPUT
    RunIn AT %Q0.0 : BOOL; (* Infeed.run: run the infeed belt *)
    RunOut AT %Q0.1 : BOOL; (* Outfeed.run: run the belt to the blue bin *)
    RunSide AT %Q0.2 : BOOL; (* SideBelt.run: run the belt to the red bin *)
    Hold AT %Q0.3 : BOOL; (* Blade1.extend: the blade holds the workpiece while true *)
    Push AT %Q0.4 : BOOL; (* Pusher1.extend: push the workpiece onto the side belt *)
    Busy AT %Q0.5 : BOOL; (* Beacon.amber: the line is running *)
    Done AT %Q0.6 : BOOL; (* Beacon.green: all eight workpieces are handled *)
END_VAR

(* LD Execution - Auto-generated *)

(* Rung 1: Start: a press latches the line on. *)
_rung1_result := Start;
IF _rung1_result THEN Active := TRUE; END_IF;

(* Rung 2: Settle time: the workpiece must lie still against the blade for a moment before its colour is read. *)
_rung2_result := State = 0;
_rung2_result_2 := _rung2_result AND Waiting;
Settle(IN := _rung2_result_2, PT := T#300ms);

(* Rung 3: Clear time: a blue workpiece has gone by when the beam has been free for a while. *)
_rung3_result := State = 3;
_rung3_result_2 := _rung3_result AND NOT Waiting;
Clear(IN := _rung3_result_2, PT := T#1500ms);

(* Rung 4: Count a workpiece when the plate is back or the blue one has gone by. *)
_rung4_result := State = 2;
_rung4_result_2 := State = 3;
_rung4_result_3 := (_rung4_result AND Retracted) OR (_rung4_result_2 AND Clear.Q);
Handled(CU := _rung4_result_3, R := FALSE, PV := 8);

(* Rung 5: State 3, blue workpiece gone: wait for the next one. *)
_rung5_result := State = 3;
_rung5_result_2 := _rung5_result AND Clear.Q;
IF _rung5_result_2 THEN State := 0; END_IF;

(* Rung 6: State 2, plate back: wait for the next workpiece. *)
_rung6_result := State = 2;
_rung6_result_2 := _rung6_result AND Retracted;
IF _rung6_result_2 THEN State := 0; END_IF;

(* Rung 7: State 1, plate out: pull it back. *)
_rung7_result := State = 1;
_rung7_result_2 := _rung7_result AND Extended;
IF _rung7_result_2 THEN State := 2; END_IF;

(* Rung 8: State 0, a red workpiece lies still: push it out. *)
_rung8_result := State = 0;
_rung8_result_2 := _rung8_result AND Active AND Settle.Q AND IsRed;
IF _rung8_result_2 THEN State := 1; END_IF;

(* Rung 9: State 0, a blue workpiece lies still: let it go. *)
_rung9_result := State = 0;
_rung9_result_2 := _rung9_result AND Active AND Settle.Q AND NOT IsRed;
IF _rung9_result_2 THEN State := 3; END_IF;

(* Rung 10: The infeed belt runs while the line is active. *)
_rung10_result := Active;
RunIn := _rung10_result;

(* Rung 11: The outfeed belt runs while the line is active. *)
_rung11_result := Active;
RunOut := _rung11_result;

(* Rung 12: The side belt runs while the line is active. *)
_rung12_result := Active;
RunSide := _rung12_result;

(* Rung 13: The blade lets a blue workpiece go and holds everything else. *)
_rung13_result := State <> 3;
_rung13_result_2 := Active AND _rung13_result;
Hold := _rung13_result_2;

(* Rung 14: Push: the plate pushes out in state 1. *)
_rung14_result := State = 1;
Push := _rung14_result;

(* Rung 15: Done: lit when eight workpieces are handled. *)
_rung15_result := Handled.Q;
Done := _rung15_result;

(* Rung 16: Busy: lit while the line runs and not yet done. *)
_rung16_result := Active AND NOT Handled.Q;
Busy := _rung16_result;

END_PROGRAM

