PROGRAM CountedQueue

VAR_INPUT
    Start AT %I0.0 : BOOL; (* StartButton.pressed: start the batch *)
    EyeIn AT %I0.1 : BOOL; (* EyeIn.detect: sees each box that has been loaded *)
    EyeOut AT %I0.2 : BOOL; (* EyeOut.detect: sees each box about to be unloaded *)
END_VAR

VAR
    Active : BOOL; (* Memory: the batch has been started *)
    Loaded : CTU; (* Counts the boxes loaded at EyeIn *)
    Unloaded : CTU; (* Counts the boxes unloaded at EyeOut *)
    LoadedQ : BOOL; (* Loaded.Q: three boxes have been loaded *)
    UnloadedQ : BOOL; (* Unloaded.Q: three boxes have been unloaded *)
    _rung1_result : BOOL;
    _rung2_result : BOOL;
    _rung3_result : BOOL;
    _rung4_result : BOOL;
    _edge_r4_r4_1_0 : F_TRIG;
    _rung5_result : BOOL;
    _rung6_result : BOOL;
END_VAR

VAR_OUTPUT
    Run AT %Q0.0 : BOOL; (* Belt1.run: run the belt *)
    Emit AT %Q0.1 : BOOL; (* Emitter1.emit: put one box on the belt *)
    Done AT %Q0.2 : BOOL; (* DoneLight.lit: lit when the batch is finished *)
END_VAR

(* LD Execution - Auto-generated *)

(* Rung 1: Start remembers that the batch is active. *)
_rung1_result := Start;
IF _rung1_result THEN Active := TRUE; END_IF;

(* Rung 2: The first counter counts the boxes that pass EyeIn. *)
_rung2_result := EyeIn;
Loaded(CU := _rung2_result, R := FALSE, PV := 3);
LoadedQ := Loaded.Q;

(* Rung 3: The second counter counts the boxes that pass EyeOut. *)
_rung3_result := EyeOut;
Unloaded(CU := _rung3_result, R := FALSE, PV := 3);
UnloadedQ := Unloaded.Q;

(* Rung 4: The first box on Start, each next box once the previous one has left EyeIn, until three are loaded. *)
_edge_r4_r4_1_0(CLK := EyeIn);
_rung4_result := (Start OR _edge_r4_r4_1_0.Q) AND Active AND NOT LoadedQ;
Emit := _rung4_result;

(* Rung 5: Done lights when the second counter reaches 3. *)
_rung5_result := UnloadedQ;
Done := _rung5_result;

(* Rung 6: The belt runs from the start until the third box is out. *)
_rung6_result := Active AND NOT UnloadedQ;
Run := _rung6_result;

END_PROGRAM

