PROGRAM ThreeLevelLifts

VAR_INPUT
    Start AT %IX0.0 : BOOL; (* StartButton.pressed: start the line *)
    EStopOk AT %IX0.1 : BOOL; (* EStop1.ok: TRUE while the emergency stop is released *)
    BoxOnA AT %IX0.2 : BOOL; (* EyeFoot.detect: a box has reached the middle of lift A at level 1 *)
    BoxOnB AT %IX0.3 : BOOL; (* EyeMid.detect: a box has reached the middle of lift B at its bottom level *)
    BoxAtTop AT %IX0.4 : BOOL; (* EyeTop.detect: a box is on the outfeed belt at level 3 *)
    AAtLow AT %IX0.5 : BOOL; (* LiftA.atLevel1: lift A rests at level 1 *)
    AAtHigh AT %IX0.6 : BOOL; (* LiftA.atLevel2: lift A rests at level 2 *)
    BAtLow AT %IX0.7 : BOOL; (* LiftB.atLevel1: lift B rests at its bottom level (level 2 of the plant) *)
    BAtHigh AT %IX1.0 : BOOL; (* LiftB.atLevel2: lift B rests at its top level (level 3 of the plant) *)
END_VAR

VAR
    Active : BOOL := FALSE; (* The line runs *)
    Stopped : BOOL := FALSE; (* The emergency stop was pressed and the line has not been started again *)
    StepA : INT := 0; (* Lift A: 0 load at level 1, 1 settle, 2 rise, 3 unload at level 2, 4 lower *)
    StepB : INT := 0; (* Lift B: the same sequence, one level higher *)
    SettleA : TON; (* Lift A: the box is still before the lift rises *)
    UnloadA : TON; (* Lift A: time for the box to leave at the top *)
    SettleB : TON; (* Lift B: the box is still before the lift rises *)
    UnloadB : TON; (* Lift B: time for the box to leave at the top *)
    Boxes : CTU; (* Counts the boxes that reached the top *)
    _rung1_result : BOOL;
    _rung2_result : BOOL;
    _rung3_result : BOOL;
    _rung4_result : BOOL;
    _rung5_result : BOOL;
    _rung5_result_2 : BOOL;
    _rung6_result : BOOL;
    _rung6_result_2 : BOOL;
    _rung7_result : BOOL;
    _rung7_result_2 : BOOL;
    _rung8_result : BOOL;
    _rung8_result_2 : BOOL;
    _rung9_result : BOOL;
    _rung9_result_2 : BOOL;
    _rung10_result : BOOL;
    _rung10_result_2 : BOOL;
    _rung11_result : BOOL;
    _rung11_result_2 : BOOL;
    _rung12_result : BOOL;
    _rung12_result_2 : BOOL;
    _rung13_result : BOOL;
    _rung13_result_2 : BOOL;
    _rung14_result : BOOL;
    _rung14_result_2 : BOOL;
    _rung15_result : BOOL;
    _rung15_result_2 : BOOL;
    _rung16_result : BOOL;
    _rung16_result_2 : BOOL;
    _rung17_result : BOOL;
    _rung17_result_2 : BOOL;
    _rung18_result : BOOL;
    _rung18_result_2 : BOOL;
    _rung19_result : BOOL;
    _rung20_result : BOOL;
    _rung20_result_2 : BOOL;
    _rung20_result_3 : BOOL;
    _rung21_result : BOOL;
    _rung21_result_2 : BOOL;
    _rung21_result_3 : BOOL;
    _rung22_result : BOOL;
    _rung22_result_2 : BOOL;
    _rung23_result : BOOL;
    _rung23_result_2 : BOOL;
    _rung24_result : BOOL;
    _rung24_result_2 : BOOL;
    _rung25_result : BOOL;
    _rung25_result_2 : BOOL;
    _rung26_result : BOOL;
    _rung26_result_2 : BOOL;
    _rung27_result : BOOL;
    _rung27_result_2 : BOOL;
    _rung27_result_3 : BOOL;
    _rung28_result : BOOL;
    _rung29_result : BOOL;
    _rung30_result : BOOL;
END_VAR

VAR_OUTPUT
    RunInfeed AT %QX0.0 : BOOL; (* Infeed.run: run the belt that feeds lift A *)
    RunTransfer AT %QX0.1 : BOOL; (* Transfer.run: run the belt between the lifts, level 2 *)
    RunOutfeed AT %QX0.2 : BOOL; (* Outfeed.run: run the belt to the bin, level 3 *)
    AUp AT %QX0.3 : BOOL; (* LiftA.up: raise lift A *)
    ADown AT %QX0.4 : BOOL; (* LiftA.down: lower lift A *)
    ARun AT %QX0.5 : BOOL; (* LiftA.run: run the surface of lift A *)
    BUp AT %QX0.6 : BOOL; (* LiftB.up: raise lift B *)
    BDown AT %QX0.7 : BOOL; (* LiftB.down: lower lift B *)
    BRun AT %QX1.0 : BOOL; (* LiftB.run: run the surface of lift B *)
    Green AT %QX1.1 : BOOL; (* StackLight1.green: all five boxes reached the top *)
    Red AT %QX1.2 : BOOL; (* StackLight1.red: the line is stopped *)
END_VAR

(* LD Execution - Auto-generated *)

(* Rung 1: Start: a press runs the line again, but only while the emergency stop is released. *)
_rung1_result := Start AND EStopOk;
IF _rung1_result THEN Active := TRUE; END_IF;

(* Rung 2: Start: a press clears the stopped state while the emergency stop is released. *)
_rung2_result := Start AND EStopOk;
IF _rung2_result THEN Stopped := FALSE; END_IF;

(* Rung 3: The emergency stop wins over Start: pressing it marks the line stopped. *)
_rung3_result := NOT EStopOk;
IF _rung3_result THEN Stopped := TRUE; END_IF;

(* Rung 4: The emergency stop wins over Start: pressing it drops Active, and every move with it. *)
_rung4_result := NOT EStopOk;
IF _rung4_result THEN Active := FALSE; END_IF;

(* Rung 5: Lift A settle time: a box on the lift is still for a moment before it rises. *)
_rung5_result := StepA = 1;
_rung5_result_2 := Active AND _rung5_result;
SettleA(IN := _rung5_result_2, PT := T#500ms);

(* Rung 6: Lift A unload time: the surface runs while the box leaves. *)
_rung6_result := StepA = 3;
_rung6_result_2 := Active AND _rung6_result;
UnloadA(IN := _rung6_result_2, PT := T#2500ms);

(* Rung 7: Lift A, state 4: back at the bottom, ready for the next box. *)
_rung7_result := StepA = 4;
_rung7_result_2 := Active AND _rung7_result AND AAtLow;
IF _rung7_result_2 THEN StepA := 0; END_IF;

(* Rung 8: Lift A, state 3: unloaded, lower. *)
_rung8_result := StepA = 3;
_rung8_result_2 := Active AND _rung8_result AND UnloadA.Q;
IF _rung8_result_2 THEN StepA := 4; END_IF;

(* Rung 9: Lift A, state 2: at the top, unload. *)
_rung9_result := StepA = 2;
_rung9_result_2 := Active AND _rung9_result AND AAtHigh;
IF _rung9_result_2 THEN StepA := 3; END_IF;

(* Rung 10: Lift A, state 1: settled, rise. *)
_rung10_result := StepA = 1;
_rung10_result_2 := Active AND _rung10_result AND SettleA.Q;
IF _rung10_result_2 THEN StepA := 2; END_IF;

(* Rung 11: Lift A, state 0: a box is on the lift, settle. *)
_rung11_result := StepA = 0;
_rung11_result_2 := Active AND _rung11_result AND AAtLow AND BoxOnA;
IF _rung11_result_2 THEN StepA := 1; END_IF;

(* Rung 12: Lift B settle time: a box on the lift is still for a moment before it rises. *)
_rung12_result := StepB = 1;
_rung12_result_2 := Active AND _rung12_result;
SettleB(IN := _rung12_result_2, PT := T#500ms);

(* Rung 13: Lift B unload time: the surface runs while the box leaves. *)
_rung13_result := StepB = 3;
_rung13_result_2 := Active AND _rung13_result;
UnloadB(IN := _rung13_result_2, PT := T#2500ms);

(* Rung 14: Lift B, state 4: back at the bottom, ready for the next box. *)
_rung14_result := StepB = 4;
_rung14_result_2 := Active AND _rung14_result AND BAtLow;
IF _rung14_result_2 THEN StepB := 0; END_IF;

(* Rung 15: Lift B, state 3: unloaded, lower. *)
_rung15_result := StepB = 3;
_rung15_result_2 := Active AND _rung15_result AND UnloadB.Q;
IF _rung15_result_2 THEN StepB := 4; END_IF;

(* Rung 16: Lift B, state 2: at the top, unload. *)
_rung16_result := StepB = 2;
_rung16_result_2 := Active AND _rung16_result AND BAtHigh;
IF _rung16_result_2 THEN StepB := 3; END_IF;

(* Rung 17: Lift B, state 1: settled, rise. *)
_rung17_result := StepB = 1;
_rung17_result_2 := Active AND _rung17_result AND SettleB.Q;
IF _rung17_result_2 THEN StepB := 2; END_IF;

(* Rung 18: Lift B, state 0: a box is on the lift, settle. *)
_rung18_result := StepB = 0;
_rung18_result_2 := Active AND _rung18_result AND BAtLow AND BoxOnB;
IF _rung18_result_2 THEN StepB := 1; END_IF;

(* Rung 19: Count each box that reaches the outfeed at level 3. *)
_rung19_result := BoxAtTop;
Boxes(CU := _rung19_result, R := FALSE, PV := 5);

(* Rung 20: Surface of lift A: it runs only while lift A stands at the level of its step. *)
_rung20_result := StepA = 0;
_rung20_result_2 := StepA = 3;
_rung20_result_3 := Active AND ((_rung20_result AND AAtLow AND NOT BoxOnA) OR (_rung20_result_2 AND AAtHigh));
ARun := _rung20_result_3;

(* Rung 21: Surface of lift B: it runs only while lift B stands at the level of its step. *)
_rung21_result := StepB = 0;
_rung21_result_2 := StepB = 3;
_rung21_result_3 := Active AND ((_rung21_result AND BAtLow AND NOT BoxOnB) OR (_rung21_result_2 AND BAtHigh));
BRun := _rung21_result_3;

(* Rung 22: AUp: lift A rises in its rise step, with its surface stopped. *)
_rung22_result := StepA = 2;
_rung22_result_2 := Active AND _rung22_result;
AUp := _rung22_result_2;

(* Rung 23: ADown: lift A lowers in its lower step. *)
_rung23_result := StepA = 4;
_rung23_result_2 := Active AND _rung23_result;
ADown := _rung23_result_2;

(* Rung 24: BUp: lift B rises in its rise step, with its surface stopped. *)
_rung24_result := StepB = 2;
_rung24_result_2 := Active AND _rung24_result;
BUp := _rung24_result_2;

(* Rung 25: BDown: lift B lowers in its lower step. *)
_rung25_result := StepB = 4;
_rung25_result_2 := Active AND _rung25_result;
BDown := _rung25_result_2;

(* Rung 26: The infeed runs only while lift A waits at its loading level, so no box is pushed into a gap. *)
_rung26_result := StepA = 0;
_rung26_result_2 := Active AND _rung26_result AND AAtLow AND NOT BoxOnA;
RunInfeed := _rung26_result_2;

(* Rung 27: The transfer belt runs while lift A unloads, or while lift B waits at its loading level. *)
_rung27_result := StepA = 3;
_rung27_result_2 := StepB = 0;
_rung27_result_3 := Active AND (_rung27_result OR (_rung27_result_2 AND BAtLow AND NOT BoxOnB));
RunTransfer := _rung27_result_3;

(* Rung 28: The outfeed belt runs while the line runs. *)
_rung28_result := Active;
RunOutfeed := _rung28_result;

(* Rung 29: Green: all five boxes reached the top. *)
_rung29_result := Boxes.Q;
Green := _rung29_result;

(* Rung 30: Red: the line is stopped. *)
_rung30_result := Stopped;
Red := _rung30_result;

END_PROGRAM

PROGRAM ThreeLevelLifts

VAR_INPUT
    Start AT %IX0.0 : BOOL; (* StartButton.pressed: start the line *)
    EStopOk AT %IX0.1 : BOOL; (* EStop1.ok: TRUE while the emergency stop is released *)
    BoxOnA AT %IX0.2 : BOOL; (* EyeFoot.detect: a box has reached the middle of lift A at level 1 *)
    BoxOnB AT %IX0.3 : BOOL; (* EyeMid.detect: a box has reached the middle of lift B at its bottom level *)
    BoxAtTop AT %IX0.4 : BOOL; (* EyeTop.detect: a box is on the outfeed belt at level 3 *)
    AAtLow AT %IX0.5 : BOOL; (* LiftA.atLevel1: lift A rests at level 1 *)
    AAtHigh AT %IX0.6 : BOOL; (* LiftA.atLevel2: lift A rests at level 2 *)
    BAtLow AT %IX0.7 : BOOL; (* LiftB.atLevel1: lift B rests at its bottom level (level 2 of the plant) *)
    BAtHigh AT %IX1.0 : BOOL; (* LiftB.atLevel2: lift B rests at its top level (level 3 of the plant) *)
END_VAR

VAR
    Active : BOOL := FALSE; (* The line runs *)
    StepA : INT := 0; (* Lift A: 0 load at level 1, 1 settle, 2 rise, 3 unload at level 2, 4 lower *)
    StepB : INT := 0; (* Lift B: the same sequence, one level higher *)
    SettleA : TON; (* Lift A: the box is still before the lift rises *)
    UnloadA : TON; (* Lift A: time for the box to leave at the top *)
    SettleB : TON; (* Lift B: the box is still before the lift rises *)
    UnloadB : TON; (* Lift B: time for the box to leave at the top *)
    Boxes : CTU; (* Counts the boxes that reached the top *)
    _rung1_result : BOOL;
    _rung2_result : BOOL;
    _rung2_result_2 : BOOL;
    _rung3_result : BOOL;
    _rung3_result_2 : BOOL;
    _rung4_result : BOOL;
    _rung4_result_2 : BOOL;
    _rung5_result : BOOL;
    _rung5_result_2 : BOOL;
    _rung6_result : BOOL;
    _rung6_result_2 : BOOL;
    _rung7_result : BOOL;
    _rung7_result_2 : BOOL;
    _rung8_result : BOOL;
    _rung8_result_2 : BOOL;
    _rung9_result : BOOL;
    _rung9_result_2 : BOOL;
    _rung10_result : BOOL;
    _rung10_result_2 : BOOL;
    _rung11_result : BOOL;
    _rung11_result_2 : BOOL;
    _rung12_result : BOOL;
    _rung12_result_2 : BOOL;
    _rung13_result : BOOL;
    _rung13_result_2 : BOOL;
    _rung14_result : BOOL;
    _rung14_result_2 : BOOL;
    _rung15_result : BOOL;
    _rung15_result_2 : BOOL;
    _rung16_result : BOOL;
    _rung17_result : BOOL;
    _rung17_result_2 : BOOL;
    _rung17_result_3 : BOOL;
    _rung18_result : BOOL;
    _rung18_result_2 : BOOL;
    _rung18_result_3 : BOOL;
    _rung19_result : BOOL;
    _rung19_result_2 : BOOL;
    _rung20_result : BOOL;
    _rung20_result_2 : BOOL;
    _rung21_result : BOOL;
    _rung21_result_2 : BOOL;
    _rung22_result : BOOL;
    _rung22_result_2 : BOOL;
    _rung23_result : BOOL;
    _rung23_result_2 : BOOL;
    _rung24_result : BOOL;
    _rung24_result_2 : BOOL;
    _rung24_result_3 : BOOL;
    _rung25_result : BOOL;
    _rung26_result : BOOL;
END_VAR

VAR_OUTPUT
    RunInfeed AT %QX0.0 : BOOL; (* Infeed.run: run the belt that feeds lift A *)
    RunTransfer AT %QX0.1 : BOOL; (* Transfer.run: run the belt between the lifts, level 2 *)
    RunOutfeed AT %QX0.2 : BOOL; (* Outfeed.run: run the belt to the bin, level 3 *)
    AUp AT %QX0.3 : BOOL; (* LiftA.up: raise lift A *)
    ADown AT %QX0.4 : BOOL; (* LiftA.down: lower lift A *)
    ARun AT %QX0.5 : BOOL; (* LiftA.run: run the surface of lift A *)
    BUp AT %QX0.6 : BOOL; (* LiftB.up: raise lift B *)
    BDown AT %QX0.7 : BOOL; (* LiftB.down: lower lift B *)
    BRun AT %QX1.0 : BOOL; (* LiftB.run: run the surface of lift B *)
    Green AT %QX1.1 : BOOL; (* StackLight1.green: all five boxes reached the top *)
    Red AT %QX1.2 : BOOL; (* StackLight1.red: the line is stopped *)
END_VAR

(* LD Execution - Auto-generated *)

(* Rung 1: Start runs the line; nothing stops it yet. Goal: while EStopOk is FALSE every output is FALSE and Red is TRUE; releasing the stop must not restart the line, only a new press of Start does. *)
_rung1_result := Start;
IF _rung1_result THEN Active := TRUE; END_IF;

(* Rung 2: Lift A settle time: a box on the lift is still for a moment before it rises. *)
_rung2_result := StepA = 1;
_rung2_result_2 := Active AND _rung2_result;
SettleA(IN := _rung2_result_2, PT := T#500ms);

(* Rung 3: Lift A unload time: the surface runs while the box leaves. *)
_rung3_result := StepA = 3;
_rung3_result_2 := Active AND _rung3_result;
UnloadA(IN := _rung3_result_2, PT := T#2500ms);

(* Rung 4: Lift A, state 4: back at the bottom, ready for the next box. *)
_rung4_result := StepA = 4;
_rung4_result_2 := Active AND _rung4_result AND AAtLow;
IF _rung4_result_2 THEN StepA := 0; END_IF;

(* Rung 5: Lift A, state 3: unloaded, lower. *)
_rung5_result := StepA = 3;
_rung5_result_2 := Active AND _rung5_result AND UnloadA.Q;
IF _rung5_result_2 THEN StepA := 4; END_IF;

(* Rung 6: Lift A, state 2: at the top, unload. *)
_rung6_result := StepA = 2;
_rung6_result_2 := Active AND _rung6_result AND AAtHigh;
IF _rung6_result_2 THEN StepA := 3; END_IF;

(* Rung 7: Lift A, state 1: settled, rise. *)
_rung7_result := StepA = 1;
_rung7_result_2 := Active AND _rung7_result AND SettleA.Q;
IF _rung7_result_2 THEN StepA := 2; END_IF;

(* Rung 8: Lift A, state 0: a box is on the lift, settle. *)
_rung8_result := StepA = 0;
_rung8_result_2 := Active AND _rung8_result AND AAtLow AND BoxOnA;
IF _rung8_result_2 THEN StepA := 1; END_IF;

(* Rung 9: Lift B settle time: a box on the lift is still for a moment before it rises. *)
_rung9_result := StepB = 1;
_rung9_result_2 := Active AND _rung9_result;
SettleB(IN := _rung9_result_2, PT := T#500ms);

(* Rung 10: Lift B unload time: the surface runs while the box leaves. *)
_rung10_result := StepB = 3;
_rung10_result_2 := Active AND _rung10_result;
UnloadB(IN := _rung10_result_2, PT := T#2500ms);

(* Rung 11: Lift B, state 4: back at the bottom, ready for the next box. *)
_rung11_result := StepB = 4;
_rung11_result_2 := Active AND _rung11_result AND BAtLow;
IF _rung11_result_2 THEN StepB := 0; END_IF;

(* Rung 12: Lift B, state 3: unloaded, lower. *)
_rung12_result := StepB = 3;
_rung12_result_2 := Active AND _rung12_result AND UnloadB.Q;
IF _rung12_result_2 THEN StepB := 4; END_IF;

(* Rung 13: Lift B, state 2: at the top, unload. *)
_rung13_result := StepB = 2;
_rung13_result_2 := Active AND _rung13_result AND BAtHigh;
IF _rung13_result_2 THEN StepB := 3; END_IF;

(* Rung 14: Lift B, state 1: settled, rise. *)
_rung14_result := StepB = 1;
_rung14_result_2 := Active AND _rung14_result AND SettleB.Q;
IF _rung14_result_2 THEN StepB := 2; END_IF;

(* Rung 15: Lift B, state 0: a box is on the lift, settle. *)
_rung15_result := StepB = 0;
_rung15_result_2 := Active AND _rung15_result AND BAtLow AND BoxOnB;
IF _rung15_result_2 THEN StepB := 1; END_IF;

(* Rung 16: Count each box that reaches the outfeed at level 3. *)
_rung16_result := BoxAtTop;
Boxes(CU := _rung16_result, R := FALSE, PV := 5);

(* Rung 17: Surface of lift A: it runs only while lift A stands at the level of its step. *)
_rung17_result := StepA = 0;
_rung17_result_2 := StepA = 3;
_rung17_result_3 := Active AND ((_rung17_result AND AAtLow AND NOT BoxOnA) OR (_rung17_result_2 AND AAtHigh));
ARun := _rung17_result_3;

(* Rung 18: Surface of lift B: it runs only while lift B stands at the level of its step. *)
_rung18_result := StepB = 0;
_rung18_result_2 := StepB = 3;
_rung18_result_3 := Active AND ((_rung18_result AND BAtLow AND NOT BoxOnB) OR (_rung18_result_2 AND BAtHigh));
BRun := _rung18_result_3;

(* Rung 19: AUp: lift A rises in its rise step, with its surface stopped. *)
_rung19_result := StepA = 2;
_rung19_result_2 := Active AND _rung19_result;
AUp := _rung19_result_2;

(* Rung 20: ADown: lift A lowers in its lower step. *)
_rung20_result := StepA = 4;
_rung20_result_2 := Active AND _rung20_result;
ADown := _rung20_result_2;

(* Rung 21: BUp: lift B rises in its rise step, with its surface stopped. *)
_rung21_result := StepB = 2;
_rung21_result_2 := Active AND _rung21_result;
BUp := _rung21_result_2;

(* Rung 22: BDown: lift B lowers in its lower step. *)
_rung22_result := StepB = 4;
_rung22_result_2 := Active AND _rung22_result;
BDown := _rung22_result_2;

(* Rung 23: The infeed runs only while lift A waits at its loading level, so no box is pushed into a gap. *)
_rung23_result := StepA = 0;
_rung23_result_2 := Active AND _rung23_result AND AAtLow AND NOT BoxOnA;
RunInfeed := _rung23_result_2;

(* Rung 24: The transfer belt runs while lift A unloads, or while lift B waits at its loading level. *)
_rung24_result := StepA = 3;
_rung24_result_2 := StepB = 0;
_rung24_result_3 := Active AND (_rung24_result OR (_rung24_result_2 AND BAtLow AND NOT BoxOnB));
RunTransfer := _rung24_result_3;

(* Rung 25: The outfeed belt runs while the line runs. *)
_rung25_result := Active;
RunOutfeed := _rung25_result;

(* Rung 26: Green: all five boxes reached the top. *)
_rung26_result := Boxes.Q;
Green := _rung26_result;

END_PROGRAM

