PROGRAM HeightSortChain

VAR_INPUT
    Start AT %I0.0 : BOOL; (* StartButton.pressed: start the line *)
    Low AT %I0.1 : BOOL; (* BeamLow.detect: the low beam (0.25 m) is broken *)
    High AT %I0.2 : BOOL; (* BeamHigh.detect: the high beam (0.35 m) is broken *)
    AtBlade AT %I0.3 : BOOL; (* EyeBlade.detect: a box waits against the blade *)
    Raised AT %I0.4 : BOOL; (* Chain1.raised: the chain module is up *)
    Lowered AT %I0.5 : BOOL; (* Chain1.lowered: the chain module is down *)
END_VAR

VAR
    Active : BOOL := FALSE; (* The line was started *)
    State : INT := 0; (* One state per step: 0 idle, 1 wait for a box, 2 straight on (short), 3 lift, 4 slide sideways, 5 lower *)
    Dir : INT := 0; (* Where the box goes: 0 short (straight), 1 medium (right), 2 tall (left) *)
    SawLow : BOOL := FALSE; (* The box broke the low beam *)
    SawHigh : BOOL := FALSE; (* The box broke the high beam *)
    Stand : TON; (* A box must stand still against the blade before anything moves *)
    Clear : TON; (* Time for a short box to cross the module *)
    Lifted : TON; (* A moment at the top before the module slides a box *)
    Slide : TON; (* Time to slide a box off the module *)
    Handled : CTU; (* Counts the boxes dealt with *)
    _rung1_result : BOOL;
    _rung2_result : BOOL;
    _rung3_result : BOOL;
    _rung4_result : BOOL;
    _rung4_result_2 : BOOL;
    _rung5_result : BOOL;
    _rung6_result : BOOL;
    _rung6_result_2 : BOOL;
    _rung7_result : BOOL;
    _rung8_result : BOOL;
    _rung8_result_2 : BOOL;
    _rung8_result_3 : BOOL;
    _rung9_result : BOOL;
    _rung9_result_2 : BOOL;
    _rung10_result : BOOL;
    _rung10_result_2 : BOOL;
    _rung11_result : BOOL;
    _rung11_result_2 : BOOL;
    _rung12_result : BOOL;
    _rung12_result_2 : BOOL;
    _rung13_result : BOOL;
    _rung13_result_2 : BOOL;
    _rung14_result : BOOL;
    _rung14_result_2 : BOOL;
    _rung15_result : BOOL;
    _rung15_result_2 : BOOL;
    _rung16_result : BOOL;
    _rung16_result_2 : BOOL;
    _rung16_result_3 : BOOL;
    _rung17_result : BOOL;
    _rung17_result_2 : BOOL;
    _rung17_result_3 : BOOL;
    _rung18_result : BOOL;
    _rung19_result : BOOL;
    _rung20_result : BOOL;
    _rung20_result_2 : BOOL;
    _rung21_result : BOOL;
    _rung22_result : BOOL;
    _rung23_result : BOOL;
    _rung24_result : BOOL;
    _rung25_result : BOOL;
    _rung25_result_2 : BOOL;
    _rung25_result_3 : BOOL;
    _rung26_result : BOOL;
    _rung26_result_2 : BOOL;
    _rung27_result : BOOL;
    _rung27_result_2 : BOOL;
    _rung27_result_3 : BOOL;
    _rung28_result : BOOL;
    _rung28_result_2 : BOOL;
    _rung28_result_3 : BOOL;
    _rung29_result : BOOL;
    _rung29_result_2 : BOOL;
    _rung29_result_3 : BOOL;
    _rung30_result : BOOL;
    _rung31_result : BOOL;
END_VAR

VAR_OUTPUT
    RunIn AT %Q0.0 : BOOL; (* Infeed.run: run the infeed belt *)
    RunChain AT %Q0.1 : BOOL; (* Chain1.run: run the chain module surface *)
    Lift AT %Q0.2 : BOOL; (* Chain1.lift: lift the chain module *)
    MoveRight AT %Q0.3 : BOOL; (* Chain1.right: slide the chain module right *)
    MoveLeft AT %Q0.4 : BOOL; (* Chain1.left: slide the chain module left *)
    RunStraight AT %Q0.5 : BOOL; (* Straight.run: run the belt to the short bin *)
    RunRight AT %Q0.6 : BOOL; (* RightBelt.run: run the belt to the medium bin *)
    RunLeft AT %Q0.7 : BOOL; (* LeftBelt.run: run the belt to the tall bin *)
    Hold AT %Q1.0 : BOOL; (* Blade1.extend: the blade holds the box while true *)
    Busy AT %Q1.1 : BOOL; (* Beacon.amber: the line is running *)
    Done AT %Q1.2 : BOOL; (* Beacon.green: all nine boxes are handled *)
END_VAR

(* LD Execution - Auto-generated *)

(* Rung 1: Start: a press latches the line on. *)
_rung1_result := Start;
IF _rung1_result THEN Active := TRUE; END_IF;

(* Rung 2: Low beam: the latch keeps what the box showed while it passed. *)
_rung2_result := Low;
IF _rung2_result THEN SawLow := TRUE; END_IF;

(* Rung 3: High beam: the latch keeps what the box showed while it passed. *)
_rung3_result := High;
IF _rung3_result THEN SawHigh := TRUE; END_IF;

(* Rung 4: Stand time: the box must stand still against the blade before anything moves. *)
_rung4_result := State = 1;
_rung4_result_2 := _rung4_result AND AtBlade;
Stand(IN := _rung4_result_2, PT := T#1000ms);

(* Rung 5: Clear time: a short box crosses the module. *)
_rung5_result := State = 2;
Clear(IN := _rung5_result, PT := T#2200ms);

(* Rung 6: Lifted time: a moment at the top before the module slides a box. *)
_rung6_result := State = 3;
_rung6_result_2 := _rung6_result AND Raised;
Lifted(IN := _rung6_result_2, PT := T#300ms);

(* Rung 7: Slide time: time to slide a box off the module. *)
_rung7_result := State = 4;
Slide(IN := _rung7_result, PT := T#1600ms);

(* Rung 8: Count a box when a short one has crossed or the module is back down. *)
_rung8_result := State = 2;
_rung8_result_2 := State = 5;
_rung8_result_3 := (_rung8_result AND Clear.Q) OR (_rung8_result_2 AND Lowered);
Handled(CU := _rung8_result_3, R := FALSE, PV := 9);

(* Rung 9: State 5, lower: when the module is down, wait for the next box. *)
_rung9_result := State = 5;
_rung9_result_2 := _rung9_result AND Lowered;
IF _rung9_result_2 THEN State := 1; END_IF;

(* Rung 10: State 4, slide: when the box has gone, lower. *)
_rung10_result := State = 4;
_rung10_result_2 := _rung10_result AND Slide.Q;
IF _rung10_result_2 THEN State := 5; END_IF;

(* Rung 11: State 3, lift: when the module has been up for a moment, slide. *)
_rung11_result := State = 3;
_rung11_result_2 := _rung11_result AND Lifted.Q;
IF _rung11_result_2 THEN State := 4; END_IF;

(* Rung 12: State 2, straight on: when the short box has crossed, wait for the next box. *)
_rung12_result := State = 2;
_rung12_result_2 := _rung12_result AND Clear.Q;
IF _rung12_result_2 THEN State := 1; END_IF;

(* Rung 13: State 1, tall box: it broke the high beam, so it goes left. *)
_rung13_result := State = 1;
_rung13_result_2 := _rung13_result AND Stand.Q AND SawHigh;
IF _rung13_result_2 THEN Dir := 2; END_IF;

(* Rung 14: State 1, medium box: it broke only the low beam, so it goes right. *)
_rung14_result := State = 1;
_rung14_result_2 := _rung14_result AND Stand.Q AND NOT SawHigh AND SawLow;
IF _rung14_result_2 THEN Dir := 1; END_IF;

(* Rung 15: State 1, short box: it broke neither beam, so it goes straight on. *)
_rung15_result := State = 1;
_rung15_result_2 := _rung15_result AND Stand.Q AND NOT SawHigh AND NOT SawLow;
IF _rung15_result_2 THEN Dir := 0; END_IF;

(* Rung 16: State 1, short box: straight on. *)
_rung16_result := State = 1;
_rung16_result_2 := Dir = 0;
_rung16_result_3 := _rung16_result AND Stand.Q AND _rung16_result_2;
IF _rung16_result_3 THEN State := 2; END_IF;

(* Rung 17: State 1, tall or medium box: lift. *)
_rung17_result := State = 1;
_rung17_result_2 := Dir <> 0;
_rung17_result_3 := _rung17_result AND Stand.Q AND _rung17_result_2;
IF _rung17_result_3 THEN State := 3; END_IF;

(* Rung 18: The next box passes the beams before this one is done: clear the low latch now, when the decision is made. *)
_rung18_result := Stand.Q;
IF _rung18_result THEN SawLow := FALSE; END_IF;

(* Rung 19: The next box passes the beams before this one is done: clear the high latch now, when the decision is made. *)
_rung19_result := Stand.Q;
IF _rung19_result THEN SawHigh := FALSE; END_IF;

(* Rung 20: State 0, idle: the start moves the line to wait for a box. *)
_rung20_result := State = 0;
_rung20_result_2 := _rung20_result AND Active;
IF _rung20_result_2 THEN State := 1; END_IF;

(* Rung 21: The infeed belt runs while the line is active. *)
_rung21_result := Active;
RunIn := _rung21_result;

(* Rung 22: The straight belt runs while the line is active. *)
_rung22_result := Active;
RunStraight := _rung22_result;

(* Rung 23: The right belt runs while the line is active. *)
_rung23_result := Active;
RunRight := _rung23_result;

(* Rung 24: The left belt runs while the line is active. *)
_rung24_result := Active;
RunLeft := _rung24_result;

(* Rung 25: The module carries a box straight on while it is down; with lift it must not run (a conflict). *)
_rung25_result := State = 1;
_rung25_result_2 := State = 2;
_rung25_result_3 := Active AND (_rung25_result OR _rung25_result_2);
RunChain := _rung25_result_3;

(* Rung 26: The blade holds every box except a short one crossing the module. *)
_rung26_result := State <> 2;
_rung26_result_2 := Active AND _rung26_result;
Hold := _rung26_result_2;

(* Rung 27: Lift: the module is up while it lifts and slides. *)
_rung27_result := State = 3;
_rung27_result_2 := State = 4;
_rung27_result_3 := _rung27_result OR _rung27_result_2;
Lift := _rung27_result_3;

(* Rung 28: MoveRight: slide right for a medium box. *)
_rung28_result := State = 4;
_rung28_result_2 := Dir = 1;
_rung28_result_3 := _rung28_result AND _rung28_result_2;
MoveRight := _rung28_result_3;

(* Rung 29: MoveLeft: slide left for a tall box. *)
_rung29_result := State = 4;
_rung29_result_2 := Dir = 2;
_rung29_result_3 := _rung29_result AND _rung29_result_2;
MoveLeft := _rung29_result_3;

(* Rung 30: Done: lit when nine boxes are handled. *)
_rung30_result := Handled.Q;
Done := _rung30_result;

(* Rung 31: Busy: lit while the line runs and not yet done. *)
_rung31_result := Active AND NOT Handled.Q;
Busy := _rung31_result;

END_PROGRAM

