PROGRAM ManualAuto

VAR_INPUT
    Start AT %I0.0 : BOOL; (* StartButton.pressed: start the assembly *)
    LidReady AT %I0.1 : BOOL; (* LidEye.detect: a lid waits at the lid blade *)
    BaseReady AT %I0.2 : BOOL; (* BaseEye.detect: a base waits at the base blade *)
