    ModeBtn AT %I1.0 : BOOL; (* ModeButton.pressed: each press switches between manual and automatic *)
    JogXPlus AT %I1.1 : BOOL; (* JogXPlus.pressed: jog the pad toward the base belt *)
    JogXMinus AT %I1.2 : BOOL; (* JogXMinus.pressed: jog the pad toward the lid belt *)
    JogYPlus AT %I1.3 : BOOL; (* JogYPlus.pressed: jog the pad up *)
    JogYMinus AT %I1.4 : BOOL; (* JogYMinus.pressed: jog the pad down *)
