VAR
    Auto : BOOL := FALSE; (* The mode: FALSE is manual, TRUE is automatic; the machine powers up in manual *)
    ToAuto : BOOL := FALSE; (* A mode press while in manual *)
    ToManual : BOOL := FALSE; (* A mode press while in automatic *)
