(* Rung 14: Step 11: back at the lid belt, go and wait for the next pair. *)
_rung14_result := Step = 11;
_rung14_result_2 := Cycles < 3;
_rung14_result_3 := _rung14_result AND XAtMin AND _rung14_result_2;
IF _rung14_result_3 THEN Step := 2; END_IF;

(* Rung 15: Step 10: raise the pad. *)
_rung15_result := Step = 10;
_rung15_result_2 := _rung15_result AND YAtMax;
IF _rung15_result_2 THEN Step := 11; END_IF;

(* Rung 16: Step 9: the lid is released; one assembly is done and the base may leave. *)
_rung16_result := Step = 9;
_rung16_result_2 := _rung16_result AND LetGoDone;
IF _rung16_result_2 THEN Step := 10; END_IF;
IF _rung16_result_2 THEN Cycles := Cycles + 1; END_IF;
IF _rung16_result_2 THEN FreeBase := TRUE; END_IF;

(* Rung 17: Step 8: lowered on the base belt. *)
_rung17_result := Step = 8;
_rung17_result_2 := _rung17_result AND YAtMin;
IF _rung17_result_2 THEN Step := 9; END_IF;

(* Rung 18: Step 7: carried to the base belt. *)
_rung18_result := Step = 7;
_rung18_result_2 := _rung18_result AND XAtMax;
IF _rung18_result_2 THEN Step := 8; END_IF;

(* Rung 19: Step 6: lifted. *)
_rung19_result := Step = 6;
_rung19_result_2 := _rung19_result AND YAtMax;
IF _rung19_result_2 THEN Step := 7; END_IF;

(* Rung 20: Step 5: the vacuum holds. *)
_rung20_result := Step = 5;
_rung20_result_2 := _rung20_result AND GripDone AND Gripped;
IF _rung20_result_2 THEN Step := 6; END_IF;

(* Rung 21: Step 4: lowered on the lid. *)
_rung21_result := Step = 4;
_rung21_result_2 := _rung21_result AND YAtMin;
IF _rung21_result_2 THEN Step := 5; END_IF;

(* Rung 22: Step 3: settled. *)
_rung22_result := Step = 3;
_rung22_result_2 := _rung22_result AND SettleDone;
IF _rung22_result_2 THEN Step := 4; END_IF;

(* Rung 23: Step 2: a lid and a base wait and the blade is closed. *)
_rung23_result := Step = 2;
_rung23_result_2 := _rung23_result AND LidReady AND BaseReady AND NOT FreeBase;
IF _rung23_result_2 THEN Step := 3; END_IF;

(* Rung 24: Step 1: homed, pad up and over the lid belt. *)
_rung24_result := Step = 1;
_rung24_result_2 := _rung24_result AND YAtMax AND XAtMin;
IF _rung24_result_2 THEN Step := 2; END_IF;

(* Rung 25: Step 0: a start press begins the cycle with homing. *)
_rung25_result := Step = 0;
_rung25_result_2 := _rung25_result AND Start;
IF _rung25_result_2 THEN Step := 1; END_IF;

(* Rung 26: The pad toward the base belt during the carry. *)
_rung26_result := Step = 7;
_rung26_result_2 := _rung26_result AND NOT XAtMax;
XPlus := _rung26_result_2;

(* Rung 27: The pad toward the lid belt: homing and return. *)
_rung27_result := Step = 1;
_rung27_result_2 := Step = 11;
_rung27_result_3 := (_rung27_result OR _rung27_result_2) AND NOT XAtMin;
XMinus := _rung27_result_3;

(* Rung 28: The pad up: homing and the lifts. *)
_rung28_result := Step = 1;
_rung28_result_2 := Step = 6;
_rung28_result_3 := Step = 10;
_rung28_result_4 := (_rung28_result OR _rung28_result_2 OR _rung28_result_3) AND NOT YAtMax;
YPlus := _rung28_result_4;

(* Rung 29: The pad down: the two lowerings. *)
_rung29_result := Step = 4;
_rung29_result_2 := Step = 8;
_rung29_result_3 := (_rung29_result OR _rung29_result_2) AND NOT YAtMin;
YMinus := _rung29_result_3;

(* Rung 30: The vacuum holds from the grip to the release. *)
_rung30_result := Step >= 5;
_rung30_result_2 := Step <= 8;
_rung30_result_3 := _rung30_result AND _rung30_result_2;
Grip := _rung30_result_3;

(* Rung 31: Belts run while the assembly is on. *)
_rung31_result := Active;
RunLid := _rung31_result;

(* Rung 32: Base belt. *)
_rung32_result := Active;
RunBase := _rung32_result;

(* Rung 33: Exit belt. *)
_rung33_result := Active;
RunExit := _rung33_result;

(* Rung 34: The lid blade holds the lid. *)
_rung34_result := Active;
HoldLid := _rung34_result;

(* Rung 35: The base blade holds the base until the assembled one leaves. *)
_rung35_result := Active AND NOT FreeBase;
HoldBase := _rung35_result;

(* Rung 36: Green when three assemblies are done. *)
_rung36_result := Step = 12;
Green := _rung36_result;

(* Rung 37: Amber while the assembly runs. *)
_rung37_result := Step <> 12;
_rung37_result_2 := Active AND _rung37_result;
Amber := _rung37_result_2;

END_PROGRAM

packages/zplc-ide/projects/plant_merge_l.text:
PROGRAM MergeLines

VAR_INPUT
    Start AT %I0.0 : BOOL; (* StartButton.pressed: start the line *)
    WaitA AT %I0.1 : BOOL; (* EyeA.detect: a box waits at the blade of feeder A *)
    WaitB AT %I0.2 : BOOL; (* EyeB.detect: a box waits at the blade of feeder B *)
    Zone AT %I0.3 : BOOL; (* EyeZone.detect: a box is on the outfeed past the merge *)
END_VAR

VAR
    Active : BOOL; (* Memory: the line has been started *)
    GrantA : BOOL; (* Line A has the grant *)
    GrantB : BOOL; (* Line B has the grant *)
    Seen : BOOL; (* The box of the grant has been seen in the zone *)
    LoadedA : CTU; (* Counts the boxes loaded on feeder A *)
    LoadedB : CTU; (* Counts the boxes loaded on feeder B *)
    Merged : CTU; (* Counts the boxes that have left the zone *)
    LoadedAQ : BOOL; (* LoadedA.Q: three boxes loaded on A *)
    LoadedBQ : BOOL; (* LoadedB.Q: three boxes loaded on B *)
    MergedQ : BOOL; (* Merged.Q: all six boxes have left *)
    _rung1_result : BOOL;
    _rung2_result : BOOL;
    _edge_r2_r2_1_0 : F_TRIG;
    _rung3_result : BOOL;
    _edge_r3_r3_1_0 : F_TRIG;
    _rung4_result : BOOL;
    _edge_r4_r4_0_0 : F_TRIG;
    _rung5_result : BOOL;
    _edge_r5_r5_0_0 : F_TRIG;
    _rung6_result : BOOL;
    _rung7_result : BOOL;
    _rung8_result : BOOL;
    _rung9_result : BOOL;
    _edge_r9_r9_0_1 : F_TRIG;
    _rung10_result : BOOL;
    _edge_r10_r10_0_1 : F_TRIG;
    _rung11_result : BOOL;
    _edge_r11_r11_0_1 : F_TRIG;
    _rung12_result : BOOL;
    _edge_r12_r12_0_0 : F_TRIG;
    _rung13_result : BOOL;
    _rung14_result : BOOL;
    _rung15_result : BOOL;
    _rung16_result : BOOL;
    _rung17_result : BOOL;
    _rung18_result : BOOL;
END_VAR

VAR_OUTPUT
    RunA AT %Q0.0 : BOOL; (* FeedA.run: run feeder A *)
    RunB AT %Q0.1 : BOOL; (* FeedB.run: run feeder B *)
    RunOut AT %Q0.2 : BOOL; (* Outfeed.run: run the outfeed belt *)
    EmitA AT %Q0.3 : BOOL; (* EmitterA.emit: put one box on feeder A *)
    EmitB AT %Q0.4 : BOOL; (* EmitterB.emit: put one box on feeder B *)
    HoldA AT %Q0.5 : BOOL; (* BladeA.extend: the blade holds feeder A while true *)
    HoldB AT %Q0.6 : BOOL; (* BladeB.extend: the blade holds feeder B while true *)
    Done AT %Q0.7 : BOOL; (* DoneLight.lit: lit when all six boxes have left *)
END_VAR

(* LD Execution - Auto-generated *)

(* Rung 1: Start remembers that the line is active. *)
_rung1_result := Start;
IF _rung1_result THEN Active := TRUE; END_IF;

(* Rung 2: Feeder A is loaded with three boxes: the first on Start, the next once the previous has left the blade. *)
_edge_r2_r2_1_0(CLK := WaitA);
_rung2_result := (Start OR _edge_r2_r2_1_0.Q) AND Active AND NOT LoadedAQ;
EmitA := _rung2_result;

(* Rung 3: Feeder B likewise. *)
_edge_r3_r3_1_0(CLK := WaitB);
_rung3_result := (Start OR _edge_r3_r3_1_0.Q) AND Active AND NOT LoadedBQ;
EmitB := _rung3_result;

(* Rung 4: Count the boxes that left the blade of A. *)
_edge_r4_r4_0_0(CLK := WaitA);
_rung4_result := _edge_r4_r4_0_0.Q;
LoadedA(CU := _rung4_result, R := FALSE, PV := 3);
LoadedAQ := LoadedA.Q;

(* Rung 5: Count the boxes that left the blade of B. *)
_edge_r5_r5_0_0(CLK := WaitB);
_rung5_result := _edge_r5_r5_0_0.Q;
LoadedB(CU := _rung5_result, R := FALSE, PV := 3);
LoadedBQ := LoadedB.Q;

(* Rung 6: Grant to line A: only when nothing is granted and the zone is empty. It comes first, so A has priority. *)
_rung6_result := Active AND NOT GrantA AND NOT GrantB AND NOT Zone AND WaitA;
IF _rung6_result THEN GrantA := TRUE; END_IF;

(* Rung 7: Grant to line B, only when A did not take it. *)
_rung7_result := Active AND NOT GrantA AND NOT GrantB AND NOT Zone AND WaitB;
IF _rung7_result THEN GrantB := TRUE; END_IF;

(* Rung 8: Remember that the box of the grant entered the zone. *)
_rung8_result := (GrantA OR GrantB) AND Zone;
IF _rung8_result THEN Seen := TRUE; END_IF;

(* Rung 9: When the box leaves the zone, the grant of A ends. *)
_edge_r9_r9_0_1(CLK := Zone);
_rung9_result := Seen AND _edge_r9_r9_0_1.Q;
IF _rung9_result THEN GrantA := FALSE; END_IF;

(* Rung 10: When the box leaves the zone, the grant of B ends. *)
_edge_r10_r10_0_1(CLK := Zone);
_rung10_result := Seen AND _edge_r10_r10_0_1.Q;
IF _rung10_result THEN GrantB := FALSE; END_IF;

(* Rung 11: And the Seen memory is cleared. *)
_edge_r11_r11_0_1(CLK := Zone);
_rung11_result := Seen AND _edge_r11_r11_0_1.Q;
IF _rung11_result THEN Seen := FALSE; END_IF;

(* Rung 12: Count the boxes that have left the zone. *)
_edge_r12_r12_0_0(CLK := Zone);
_rung12_result := _edge_r12_r12_0_0.Q;
Merged(CU := _rung12_result, R := FALSE, PV := 6);
MergedQ := Merged.Q;

(* Rung 13: Feeder A runs while the line is active. *)
_rung13_result := Active;
RunA := _rung13_result;

(* Rung 14: Feeder B runs while the line is active. *)
_rung14_result := Active;
RunB := _rung14_result;

(* Rung 15: The outfeed runs while the line is active. *)
_rung15_result := Active;
RunOut := _rung15_result;

(* Rung 16: The blade of A holds its feeder unless A has the grant. *)
_rung16_result := Active AND NOT GrantA;
HoldA := _rung16_result;

(* Rung 17: The blade of B holds its feeder unless B has the grant. *)
_rung17_result := Active AND NOT GrantB;
HoldB := _rung17_result;

(* Rung 18: Done lights when all six boxes have left. *)
_rung18_result := MergedQ;
Done := _rung18_result;

END_PROGRAM

packages/zplc-ide/projects/plant_tank_le.text:
PROGRAM TankLevel

VAR_INPUT
    LevelRaw AT %IW0 : INT; (* Tank1.level: 0 to 27648 is 0 to 1 m *)
    SetPointRaw AT %IW1 : INT; (* SetPoint.value: 0 to 1000 is 0 to 1 m *)
    DrainRaw AT %IW2 : INT; (* DrainPot.value: 0 to 1000 is 0 to 100 percent *)
END_VAR

VAR
    LevelF : REAL; (* The raw level as a REAL *)
    SetF : REAL; (* The raw set point as a REAL *)
    DrainF : REAL; (* The raw drain value as a REAL *)
    LevelM : REAL; (* The level in m *)
    SetM : REAL; (* The set point in m *)
    Err : REAL; (* Set point minus level, in m *)
    Band : REAL; (* 5 percent of the set point, in m *)
    Lo : REAL; (* Lower edge of the green band, in m *)
    Hi : REAL; (* Upper edge of the green band, in m *)
    _rung1_result : BOOL;
    _rung2_result : BOOL;
    _rung3_result : BOOL;
    _rung4_result : BOOL;
    _rung5_result : BOOL;
    _rung6_result : BOOL;
    _rung7_result : BOOL;
    _rung7_result_2 : BOOL;
    _rung7_result_3 : BOOL;
END_VAR

VAR_OUTPUT
    FillCmd AT %QD0 : REAL; (* Tank1.fill: 0 to 100 percent of the inlet valve *)
    DrainCmd AT %QD1 : REAL; (* Tank1.drain: 0 to 100 percent of the discharge valve *)
    LevelShown AT %QD2 : REAL; (* LevelDisplay.value: the level in m *)
    Green AT %QX12.0 : BOOL; (* StackLight1.green: the level is within 5 percent of the set point *)
END_VAR

(* LD Execution - Auto-generated *)

(* Rung 1: Scale the level to metres: convert to REAL first, then divide by the raw span. *)
_rung1_result := TRUE;
IF _rung1_result THEN LevelF := LevelRaw; END_IF;
IF _rung1_result THEN LevelM := LevelF / 27648.0; END_IF;

(* Rung 2: Scale the set point to metres: 0 to 1000 is 0 to 1 m. *)
_rung2_result := TRUE;
IF _rung2_result THEN SetF := SetPointRaw; END_IF;
IF _rung2_result THEN SetM := SetF / 1000.0; END_IF;

(* Rung 3: Proportional inlet: 800 percent per metre of error, limited to 0 to 100 percent. *)
_rung3_result := TRUE;
IF _rung3_result THEN Err := SetM - LevelM; END_IF;
IF _rung3_result THEN FillCmd := 800.0 * Err; END_IF;
IF _rung3_result THEN FillCmd := LIMIT(0.0, FillCmd, 100.0); END_IF;

(* Rung 4: The operator disturbance: DrainPot opens the discharge, 0 to 1000 is 0 to 100 percent. *)
_rung4_result := TRUE;
IF _rung4_result THEN DrainF := DrainRaw; END_IF;
IF _rung4_result THEN DrainCmd := DrainF / 10.0; END_IF;

(* Rung 5: The display shows the level in m. *)
_rung5_result := TRUE;
IF _rung5_result THEN LevelShown := LevelM; END_IF;

(* Rung 6: The green band is 5 percent of the set point on each side of it. *)
_rung6_result := TRUE;
IF _rung6_result THEN Band := SetM * 0.05; END_IF;
IF _rung6_result THEN Lo := SetM - Band; END_IF;
IF _rung6_result THEN Hi := SetM + Band; END_IF;

(* Rung 7: Green while the level is inside the band. *)
_rung7_result := LevelM >= Lo;
_rung7_result_2 := LevelM <= Hi;
_rung7_result_3 := _rung7_result AND _rung7_result_2;
Green := _rung7_result_3;

END_PROGRAM

