    DrainRawR : REAL; (* Raw drain opening as a REAL *)
    Pid : PID_Compact; (* Level loop: set point to the inlet valve *)
    _lvl_div_OUT : REAL;
    _sp_div_OUT : REAL;
    _dr_div_OUT : REAL;
    _pid_OUT : REAL;
    _g_sub_OUT : REAL;
    _g_abs_OUT : REAL;
    _g_mul_OUT : REAL;
    _g_le_OUT : BOOL;
END_VAR

VAR_OUTPUT
