    LevelShown AT %QD2 : REAL; (* LevelDisplay.value: the level in m *)
    Green AT %QX12.0 : BOOL; (* StackLight1.green: the level is within 5 percent of the set point *)
END_VAR

(* FBD Execution - Auto-generated *)

(* The same number as a REAL: scale after converting *)
LevelRawR := LevelRaw;
(* Metres *)
_lvl_div_OUT := LevelRawR / 27648.0;
(* The same number as a REAL: scale after converting *)
SetPointRawR := SetPointRaw;
(* Metres *)
_sp_div_OUT := SetPointRawR / 1000.0;
(* The same number as a REAL *)
DrainRawR := DrainRaw;
(* Percent *)
_dr_div_OUT := DrainRawR / 10.0;
(* Discharge valve, percent *)
DrainCmd := _dr_div_OUT;
(* Level on the display, in m *)
LevelShown := _lvl_div_OUT;
(* Level loop: set point to the inlet valve *)
Pid(SP := _sp_div_OUT, PV := _lvl_div_OUT, KP := 800.0, KI := 10.0, KD := 150.0, DT := 0.01, OUT_MIN := 0.0, OUT_MAX := 100.0);
_pid_OUT := Pid.OUT;
(* Inlet valve, percent *)
FillCmd := _pid_OUT;
(* Error in m *)
_g_sub_OUT := _sp_div_OUT - _lvl_div_OUT;
(* Size of the error *)
_g_abs_OUT := ABS(_g_sub_OUT);
(* Band in m *)
_g_mul_OUT := 0.05 * _sp_div_OUT;
(* Within the band *)
_g_le_OUT := _g_abs_OUT <= _g_mul_OUT;
(* Level within 5 percent of the set point *)
Green := _g_le_OUT;

END_PROGRAM

