packages/zplc-ide/projects/plant_timed_t.text:
PROGRAM TimedTank

VAR_INPUT
    Start AT %I0.0 : BOOL; (* StartButton.pressed: start the cycle *)
    EStopOk AT %I0.1 : BOOL; (* EStop1.ok: TRUE while the emergency stop is released *)
    LevelLow AT %I0.2 : BOOL; (* Tank1.levelLow: the level is at or below the low switch *)
    LevelHigh AT %I0.3 : BOOL; (* Tank1.levelHigh: the level is at or above the high switch *)
END_VAR

VAR
    Step : INT := 0; (* 0 idle, 1 fill, 2 hold, 3 drain *)
    Done : BOOL; (* A cycle has finished *)
    FillT : TON; (* Times the fill *)
    HoldT : TON; (* Times the hold *)
    DrainT : TON; (* Limits the drain *)
    DrainLimit : BOOL; (* DrainT.Q: the drain has taken twenty seconds *)
    _rung1_result : BOOL;
    _rung2_result : BOOL;
    _rung2_result_2 : BOOL;
    _rung3_result : BOOL;
    _rung3_result_2 : BOOL;
    _rung4_result : BOOL;
    _rung4_result_2 : BOOL;
    _rung5_result : BOOL;
    _rung5_result_2 : BOOL;
    _rung6_result : BOOL;
    _rung7_result : BOOL;
    _rung7_result_2 : BOOL;
    _rung8_result : BOOL;
    _rung9_result : BOOL;
    _rung10_result : BOOL;
    _rung11_result : BOOL;
    _rung12_result : BOOL;
END_VAR

VAR_OUTPUT
    Fill AT %Q0.0 : BOOL; (* Tank1.fill: open the fill valve *)
    Drain AT %Q0.1 : BOOL; (* Tank1.drain: open the drain valve *)
    Green AT %Q0.2 : BOOL; (* StackLight1.green: the cycle finished *)
    Amber AT %Q0.3 : BOOL; (* StackLight1.amber: the cycle is running *)
    Red AT %Q0.4 : BOOL; (* StackLight1.red: emergency stop *)
END_VAR

(* LD Execution - Auto-generated *)

(* Rung 1: An emergency stop aborts the cycle: back to idle. *)
_rung1_result := NOT EStopOk;
IF _rung1_result THEN Step := 0; END_IF;

(* Rung 2: A Start press while idle and with the emergency stop released begins a cycle. *)
_rung2_result := Step = 0;
_rung2_result_2 := EStopOk AND _rung2_result AND Start;
IF _rung2_result_2 THEN Step := 1; END_IF;

(* Rung 3: The finished mark goes out on an emergency stop and while a cycle is running. *)
_rung3_result := Step <> 0;
_rung3_result_2 := NOT EStopOk OR _rung3_result;
IF _rung3_result_2 THEN Done := FALSE; END_IF;

(* Rung 4: Fill for a fixed time: the tank has no sensor at this level, the timer is the lesson. *)
_rung4_result := Step = 1;
FillT(IN := _rung4_result, PT := T#3500ms);
_rung4_result_2 := FillT.Q;
IF _rung4_result_2 THEN Step := 2; END_IF;

(* Rung 5: Hold for two seconds. *)
_rung5_result := Step = 2;
HoldT(IN := _rung5_result, PT := T#2s);
_rung5_result_2 := HoldT.Q;
IF _rung5_result_2 THEN Step := 3; END_IF;

(* Rung 6: Drain: the timer is a safety limit while the step is active. *)
_rung6_result := Step = 3;
DrainT(IN := _rung6_result, PT := T#20s);
DrainLimit := DrainT.Q;

(* Rung 7: The drain ends at the low switch or at the limit: back to idle and the cycle is finished. *)
_rung7_result := Step = 3;
_rung7_result_2 := _rung7_result AND (LevelLow OR DrainLimit);
IF _rung7_result_2 THEN Step := 0; END_IF;
IF _rung7_result_2 THEN Done := TRUE; END_IF;

(* Rung 8: Fill valve while the step is 1. *)
_rung8_result := Step = 1;
Fill := _rung8_result;

(* Rung 9: Drain valve while the step is 3. *)
_rung9_result := Step = 3;
Drain := _rung9_result;

(* Rung 10: Amber while a cycle is running. *)
_rung10_result := Step <> 0;
Amber := _rung10_result;

(* Rung 11: Green after a finished cycle. *)
_rung11_result := Done;
Green := _rung11_result;

(* Rung 12: Red while the emergency stop is pressed. *)
_rung12_result := NOT EStopOk;
Red := _rung12_result;

END_PROGRAM

packages/zplc-ide/projects/plant_weight_.text:
PROGRAM WeightSorter

VAR_INPUT
    Start AT %IX0.0 : BOOL; (* StartButton.pressed: start the line *)
    Stable AT %IX0.1 : BOOL; (* Scale1.stable: a box has rested on the scale long enough to be weighed *)
    Extended AT %IX0.2 : BOOL; (* Pusher1.extended: the pusher is at the end of its stroke *)
    Retracted AT %IX0.3 : BOOL; (* Pusher1.retracted: the pusher is back at rest *)
    Weight AT %ID1 : REAL; (* Scale1.weight: the weight in kg, 0 while a box moves *)
END_VAR

VAR
    Active : BOOL := FALSE; (* The line was started *)
    Step : INT := 0; (* One step per move: 0 wait for a stable box, 1 push it out, 2 pull the pusher back, 3 release it to the light bin *)
    Releasing : TON; (* The blade stays down long enough for a light box to leave the scale *)
    Boxes : CTU; (* Counts the boxes dealt with *)
    _rung1_result : BOOL;
    _rung2_result : BOOL;
    _rung3_result : BOOL;
    _rung3_result_2 : BOOL;
    _rung3_result_3 : BOOL;
    _rung4_result : BOOL;
    _rung4_result_2 : BOOL;
    _rung5_result : BOOL;
    _rung5_result_2 : BOOL;
    _rung6_result : BOOL;
    _rung6_result_2 : BOOL;
    _rung7_result : BOOL;
    _rung7_result_2 : BOOL;
    _rung7_result_3 : BOOL;
    _rung8_result : BOOL;
    _rung8_result_2 : BOOL;
    _rung8_result_3 : BOOL;
    _rung9_result : BOOL;
    _rung9_result_2 : BOOL;
    _rung9_result_3 : BOOL;
    _rung10_result : BOOL;
    _rung11_result : BOOL;
    _rung12_result : BOOL;
    _rung12_result_2 : BOOL;
    _rung13_result : BOOL;
    _rung14_result : BOOL;
END_VAR

VAR_OUTPUT
    RunInfeed AT %QX0.0 : BOOL; (* Infeed.run: run the infeed belt *)
    RunOutfeed AT %QX0.1 : BOOL; (* Outfeed.run: run the belt to the light bin *)
    RunSide AT %QX0.2 : BOOL; (* SideBelt.run: run the belt to the heavy bin *)
    Hold AT %QX0.3 : BOOL; (* Blade1.extend: the blade holds the box on the scale while true *)
    Push AT %QX0.4 : BOOL; (* Pusher1.extend: push the box off the infeed onto the side belt *)
    Green AT %QX0.5 : BOOL; (* StackLight1.green: all twelve boxes are sorted *)
END_VAR

(* LD Execution - Auto-generated *)

(* Rung 1: Start: a press latches the line on. *)
_rung1_result := Start;
IF _rung1_result THEN Active := TRUE; END_IF;

(* Rung 2: Release time: the blade stays down long enough for a light box to leave the scale and clear the blade. *)
_rung2_result := Step = 3;
Releasing(IN := _rung2_result, PT := T#2500ms);

(* Rung 3: Count a box when the pusher is back or the light box has been released. *)
_rung3_result := Step = 2;
_rung3_result_2 := Step = 3;
_rung3_result_3 := (_rung3_result AND Retracted) OR (_rung3_result_2 AND Releasing.Q);
Boxes(CU := _rung3_result_3, R := FALSE, PV := 12);

(* Rung 4: Step 3, light box released: wait for the next box. *)
_rung4_result := Step = 3;
_rung4_result_2 := _rung4_result AND Releasing.Q;
IF _rung4_result_2 THEN Step := 0; END_IF;

(* Rung 5: Step 2, pusher back: wait for the next box. *)
_rung5_result := Step = 2;
_rung5_result_2 := _rung5_result AND Retracted;
IF _rung5_result_2 THEN Step := 0; END_IF;

(* Rung 6: Step 1, pusher out: pull it back. *)
_rung6_result := Step = 1;
_rung6_result_2 := _rung6_result AND Extended;
IF _rung6_result_2 THEN Step := 2; END_IF;

(* Rung 7: Step 0, heavy box: the limit is 3.5 kg, and the box masses, 2 and 5 kg, sit 1.5 kg either side of it. Push it out. *)
_rung7_result := Step = 0;
_rung7_result_2 := Weight > 3.5;
_rung7_result_3 := _rung7_result AND Active AND Stable AND _rung7_result_2;
IF _rung7_result_3 THEN Step := 1; END_IF;

(* Rung 8: Step 0, light box: at or under the limit. Release it. *)
_rung8_result := Step = 0;
_rung8_result_2 := Weight <= 3.5;
_rung8_result_3 := _rung8_result AND Active AND Stable AND _rung8_result_2;
IF _rung8_result_3 THEN Step := 3; END_IF;

(* Rung 9: The infeed stops while the pusher works, so the belt never drags the box along the stroke. *)
_rung9_result := Step <> 1;
_rung9_result_2 := Step <> 2;
_rung9_result_3 := Active AND _rung9_result AND _rung9_result_2;
RunInfeed := _rung9_result_3;

(* Rung 10: The outfeed belt runs while the line is active. *)
_rung10_result := Active;
RunOutfeed := _rung10_result;

(* Rung 11: The side belt runs while the line is active. *)
_rung11_result := Active;
RunSide := _rung11_result;

(* Rung 12: The blade holds the box on the scale except while a light box is released. *)
_rung12_result := Step <> 3;
_rung12_result_2 := Active AND _rung12_result;
Hold := _rung12_result_2;

(* Rung 13: Push: the pusher pushes out in step 1. *)
_rung13_result := Step = 1;
Push := _rung13_result;

(* Rung 14: Green: all twelve boxes are sorted. *)
_rung14_result := Boxes.Q;
Green := _rung14_result;

END_PROGRAM

