tools/hil/fbd_tests/blinky.fbd.json.text:
PROGRAM Blinky

VAR
    OffTimer : TON; (* Times the OFF half period (500 ms) *)
    OnTimer : TON; (* Times the ON half period (500 ms); runs while the LED is ON *)
    _not_led_OUT : BOOL;
    _ton_off_Q : BOOL;
    _ton_on_Q : BOOL;
    _not_on_done_OUT : BOOL;
    _or_set_or_hold_OUT : BOOL;
    _and_run_OUT : BOOL;
END_VAR

VAR_OUTPUT
    LED_Output AT %Q0.0 : BOOL; (* Physical LED output *)
END_VAR

(* FBD Execution - Auto-generated *)

(* Invert: OffTimer runs while the LED is OFF *)
_not_led_OUT := NOT LED_Output;
(* Times the OFF half period (500 ms) *)
OffTimer(IN := _not_led_OUT, PT := T#500ms);
_ton_off_Q := OffTimer.Q;
(* Times the ON half period (500 ms); runs while the LED is ON *)
OnTimer(IN := LED_Output, PT := T#500ms);
_ton_on_Q := OnTimer.Q;
(* Invert: stop holding the LED once OnTimer is done *)
_not_on_done_OUT := NOT _ton_on_Q;
(* Set when OffTimer is done, otherwise hold the LED state *)
_or_set_or_hold_OUT := _ton_off_Q OR LED_Output;
(* LED = (OffTimer.Q OR LED) AND NOT OnTimer.Q *)
_and_run_OUT := _or_set_or_hold_OUT AND _not_on_done_OUT;
(* Physical LED output *)
LED_Output := _and_run_OUT;

END_PROGRAM

