tools/hil/ld_tests/blinky.ld.json.text:
PROGRAM Blinky

VAR
    OffTimer : TON; (* Times the OFF half period (runs while the LED is OFF) *)
    OnTimer : TON; (* Times the ON half period (runs while the LED is ON) *)
    _rung1_result : BOOL;
    _rung2_result : BOOL;
    _rung3_result : BOOL;
    _rung4_result : BOOL;
END_VAR

VAR_OUTPUT
    LED_Output AT %Q0.0 : BOOL; (* Physical LED output *)
END_VAR

(* LD Execution - Auto-generated *)

(* Rung 1: OFF phase - OffTimer runs while the LED is OFF and times 500 ms *)
_rung1_result := NOT LED_Output;
OffTimer(IN := _rung1_result, PT := T#500ms);

(* Rung 2: ON phase - OnTimer runs while the LED is ON and times 500 ms *)
_rung2_result := LED_Output;
OnTimer(IN := _rung2_result, PT := T#500ms);

(* Rung 3: OffTimer done - SET the LED (ON phase starts) *)
_rung3_result := OffTimer.Q;
IF _rung3_result THEN LED_Output := TRUE; END_IF;

(* Rung 4: OnTimer done - RESET the LED (OFF phase starts); RESET is last, so it wins *)
_rung4_result := OnTimer.Q;
IF _rung4_result THEN LED_Output := FALSE; END_IF;

END_PROGRAM

